// FILE: ai-bridge/server.js

// v3522 -- THE FIRST THING THIS PROCESS DOES IS SAY IT STARTED, AND IT SAYS SO SOMEWHERE THE OTHER PROCESS CAN
// READ. A successor that dies before listen leaves no [bridge] line, no window anybody reads (the silent update
// opens it MINIMISED) and nothing on disk -- so from the surviving old server it is indistinguishable from a
// launcher that never ran. This line is what tells those two apart, and it is first because the case it exists
// for is a process that does not get any further. See ai-bridge/bootTrace.js.
try {
    require("./bootTrace.js").record("boot", {
        root: require("path").join(__dirname, ".."),
        port: parseInt(process.env.PORT, 10) || 8787,
        argv0: process.argv[1] || null,
    });
} catch {}
// VERSION: v3 - HTTP POST INGEST + WS BROADCAST + STATIC FILE SERVING
//
// v1129 — keep-running safety net. A single feature throwing (often a Node API
// Bun doesn't implement) used to terminate the whole bridge and close the startup
// window. These handlers log and continue so the engine stays up with whatever
// features DO work. Synchronous failures inside a request are already isolated by
// the per-route try/catch; this catches the stragglers.
process.on("uncaughtException", (e) => { try { if (e && (e.code === "EADDRINUSE" || /EADDRINUSE|address already in use|port 8787 in use/i.test((e && e.message) || ""))) { console.error("\n[bridge] PORT 8787 is ALREADY IN USE — another engine/ai-bridge instance is still running.\n[bridge] Free it (Windows):  netstat -ano | findstr :8787   then   taskkill /PID <pid> /F   — or close the other window. Then relaunch.\n"); process.exit(1); } if (e && e.code === "MODULE_NOT_FOUND") {
    // v2212 -- A DEPENDENCY YOU CANNOT LOAD IS NOT SOMETHING TO CONTINUE FROM. This handler used to print
    // "continuing" and then the process fell off the end of the file with nothing left to run: it exited
    // ZERO, immediately, silently. START_NODE_Engine.bat runs `node server.js` in the FOREGROUND, so the
    // window closed with the message still in it, and the only thing left alive was the GPU Brain, which is
    // Deno and needs none of this. "The engine exits immediately, leaving only the brain" was that.
    //
    // `node_modules` is not in the shipped zip. The launcher borrows one from a sibling EngineProject_v*
    // folder or runs `npm install`; when there is no sibling and the install did not happen, `ws` is missing
    // and the bridge cannot start.
    const m = /Cannot find module '([^']+)'/.exec((e && e.message) || "");
    console.error("\n[bridge] CANNOT START: a required module is missing" + (m ? ": " + m[1] : "") + ".");
    console.error("[bridge] `node_modules` is not shipped in the zip. From WebGLEngine\\ai-bridge, run:");
    console.error("[bridge]     npm install");
    console.error("[bridge] ...then relaunch. (If npm has no network, copy `node_modules` from an older EngineProject_v* folder.)\n");
    process.exit(1);
}
console.error("[bridge] uncaughtException (continuing):", (e && e.code ? "[" + e.code + "] " : ""), (e && e.stack) || e); } catch {} });
process.on("unhandledRejection", (e) => { try { console.error("[bridge] unhandledRejection (continuing):", (e && (e.stack || e.message)) || e); } catch {} });
//
// v1148 — QUIET console mode (START_BUN.bat sets QUIET=1). Keeps the DOS window to
// critical lines only: console.warn/error always pass; routine console.log info is
// dropped unless it matches the keep-list (the "up on :8787" confirmation, the LAN
// URLs, the active RGB backend, error-ish words). The browser console is unaffected,
// and Bun's own panic prints from the runtime — so crashes are never hidden.
if (process.env.QUIET === "1") {
    const _qlog = console.log.bind(console);
    const KEEP_RE = /error|fail|panic|crash|fatal|EADDRINUSE|exception|unable|cannot|\[relay\] (HTTP\+WS|LAN access)|Starting ai-bridge/i;
    console.log = (...a) => { try { if (KEEP_RE.test(a.join(" "))) _qlog(...a); } catch { _qlog(...a); } };
}
// v1276 — capture console output into a ring buffer + live SSE stream, so the lean
// server-mode page (server.html) can show live debug (like watching the listener
// console). Independent of QUIET: stdout stays quiet, the web console sees it all.
const SYS_LOG = []; const SYS_LOG_MAX = 600; const sysLogClients = new Set();
let _lastConsoleHit = 0;   // v2330 -- last time a browser fetched server.html; a tab that's loading but hasn't yet opened its SSE still counts as "a tab is here", so the no-tab auto-open won't fire a duplicate on a slow paint.
function sysLogPush(level, args){
    let msg; try { msg = args.map(x => (typeof x === "string" ? x : (() => { try { return JSON.stringify(x); } catch { return String(x); } })())).join(" "); } catch { msg = String(args); }
    const line = { t: Date.now(), level, msg: String(msg).slice(0, 2000) };
    SYS_LOG.push(line); if (SYS_LOG.length > SYS_LOG_MAX) SYS_LOG.shift();
    const payload = "data: " + JSON.stringify(line) + "\n\n";
    for (const res of sysLogClients) { try { res.write(payload); } catch {} }
}
let _origConsole = null;
(function wrapConsole(){
    const o = { log: console.log.bind(console), warn: console.warn.bind(console), error: console.error.bind(console) };
    _origConsole = o;
    console.log = (...a) => { sysLogPush("log", a); o.log(...a); };
    console.warn = (...a) => { sysLogPush("warn", a); o.warn(...a); };
    console.error = (...a) => { sysLogPush("error", a); o.error(...a); };
})();
// v1854 — debugLog: for low-value, repetitive lines (e.g. gossip re-learning + rejecting the same
// non-LAN IP every cycle). Tagged level "debug" so the Server-console log view hides it unless the
// user ticks "Deep Debug". Still prints to the real terminal (the unwrapped console) so nothing is
// lost there, but it's pushed to the stream ONCE at debug level (not also as a normal "log" line).
function debugLog(...a){ try { sysLogPush("debug", a); } catch {} try { if (_kpopAlive()) { _kpopConsole(a.map(x => typeof x === "string" ? x : (() => { try { return JSON.stringify(x); } catch { return String(x); } })()).join(" ")); if (process.env.SWEK_QUIET_WHEN_KPOP === "1") return; } } catch {} try { (_origConsole || console).log(...a); } catch {} }
// v1174 — VERBOSE start gate. By default the DOS window shows only critical lines;
// non-critical noise (e.g. missing-asset 404s from stale prefs / unshipped packs)
// is still recorded in debug.log but kept OFF the console. Set VERBOSE=1 (or
// DEBUG_START=verbose) to surface it all.
const VERBOSE = process.env.VERBOSE === "1" || /verbose/i.test(process.env.DEBUG_START || "");
//
// VBA's modBridge.bas POSTs voxel events to http://localhost:8787/voxel-update.
// JS's RelayClient subscribes via ws://localhost:8787 and applies the events
// to the voxel world. This server is the relay between them.
//
// v3 also serves the engine's static files (index.html, all .js modules,
// shaders, GPU_Assets/, etc.) on the same port. Open http://localhost:8787/
// in a browser and the page loads — no second server needed. Same-origin
// means the WebSocket connection has zero CORS friction.
//
// Why a relay? Because the browser can't host a TCP listener for VBA to
// POST to. So VBA hits a tiny Node process; the Node process echoes to
// every connected WebSocket client. Single port, three roles now:
//   1. Static file server (GET, anything not /health or /voxel-update)
//   2. VBA POST ingest (POST /voxel-update)
//   3. WebSocket broadcast (ws upgrade)
//
// Run:
//     cd ai-bridge
//     npm install
//     node server.js
//
// Then: open http://localhost:8787/ in a browser. That's it.

const http = require("http");
const fs   = require("fs");
const net  = require("net");                  // Round 97 — KPop pipe writes
const path = require("path");
// v2759 -- ws is declared in package.json, but a FRESH machine with no `npm install` has no
// node_modules, and an unguarded require here crashed the whole server on boot (exit 1, no output) --
// so the fresh-machine path never even reached the [mdns] advice. Guard it like mdns already is: the
// server boots in a degraded mode (no live WebSocket push) and says how to enable it. wss becomes a
// null-object below so every `wss.clients` site stays safe.
let WebSocketServer = null;
try { WebSocketServer = require("ws").WebSocketServer; }
catch (e) { console.warn("[ws] websocket support disabled -- run `npm install ws` in ai-bridge/ to enable live updates"); }

// v845 — Twitch IRC chat client. Single global instance; connection
// configured at runtime via POST /twitch/connect. See twitchClient.js
// for setup instructions (OAuth token + scopes).
const { TwitchClient } = require("./twitchClient.js");
const updateManifest = require("./updateManifest.js");   // v923 — update-checker
const twitchClient = new TwitchClient();

// v1046 — Twitch EventSub (follows / subs / cheers / raids / went-live) over
// the WebSocket transport, plus a chat-commands bridge. EventSub events and
// "!cmd" chat lines are broadcast to every engine client; the engine turns
// them into toasts and (for commands) world actions.
const { TwitchEventSub } = require("./twitchEventSub.js");
const twitchEventSub = new TwitchEventSub();
const { DiscordVoice } = require("./discordVoice.js");
const discordVoice = new DiscordVoice();
let discordVoiceMirror = false;   // v1050 — mirror the avatar's TTS into the joined voice channel
let twitchChatCommandsEnabled = false;   // opt-in: chat can't drive the world until you turn this on
twitchClient.onMessage((entry) => {
    if (!twitchChatCommandsEnabled) return;
    const m = /^!(\w{1,24})(?:\s+(.{0,80}))?$/.exec(String(entry.message || "").trim());
    if (!m) return;
    try { broadcastAll({ type: "twitch:command", cmd: m[1].toLowerCase(), args: (m[2] || "").trim(), user: entry.nick }); } catch {}
});

const PORT = parseInt(process.env.PORT, 10) || 8787;   // v1238 — honor PORT env (e.g. run Node on 8788 alongside Bun on 8787)

// v521 — optional HTTPS/WSS. Phones need a SECURE CONTEXT for the camera
// (getUserMedia) and iOS gyroscope, neither of which work over plain http to a
// LAN IP. Set HTTPS=1 to serve over TLS. Cert resolution: certs/key.pem +
// certs/cert.pem if present, else auto-generate via the `selfsigned` package
// (added to deps) and cache them. Falls back to HTTP if no cert is available.
const https = require("https");

// ---- Optional MQTT mirror (opt-in via env) -------------------------------
// Set KPOP_MQTT to a broker URL to mirror every relayed event to MQTT:
//   mqtt://localhost:1883            plain
//   mqtts://host:8883                TLS (set KPOP_MQTT_CA to a CA file, or
//                                    KPOP_MQTT_INSECURE=1 for self-signed)
// Optional: KPOP_MQTT_TOPIC (default kpop/engine), KPOP_MQTT_USER, KPOP_MQTT_PASS.
// Off by default; the `mqtt` package is only require()'d when KPOP_MQTT is set,
// so a missing dependency never affects normal operation.
const MQTT_URL   = (process.env.KPOP_MQTT || "").trim();
const MQTT_TOPIC = (process.env.KPOP_MQTT_TOPIC || "kpop/engine").trim();
let mqttClient = null;
function initMqttMirror() {
    if (!MQTT_URL) return;
    let mqtt;
    try { mqtt = require("mqtt"); }
    catch { console.log("[mqtt] KPOP_MQTT is set but the 'mqtt' package isn't installed — run: npm install mqtt"); return; }
    const opts = { reconnectPeriod: 5000, connectTimeout: 8000 };
    if (process.env.KPOP_MQTT_USER) opts.username = process.env.KPOP_MQTT_USER;
    if (process.env.KPOP_MQTT_PASS) opts.password = process.env.KPOP_MQTT_PASS;
    if (MQTT_URL.startsWith("mqtts://")) {
        if (process.env.KPOP_MQTT_CA) {
            try { opts.ca = fs.readFileSync(process.env.KPOP_MQTT_CA); }
            catch (e) { console.log(`[mqtt] CA read failed (${e.message}) — continuing without it`); }
        }
        if ((process.env.KPOP_MQTT_INSECURE || "").trim() === "1") opts.rejectUnauthorized = false;
    }
    try {
        mqttClient = mqtt.connect(MQTT_URL, opts);
        mqttClient.on("connect", () => console.log(`[mqtt] connected ${MQTT_URL} -> publishing relayed events to '${MQTT_TOPIC}'`));
        mqttClient.on("error",   (e) => console.log(`[mqtt] error: ${e.message}`));
    } catch (e) {
        console.log(`[mqtt] connect failed: ${e.message}`);
        mqttClient = null;
    }
}
function mqttMirror(msg) {
    if (!mqttClient || !mqttClient.connected) return;
    try { mqttClient.publish(MQTT_TOPIC, JSON.stringify(msg)); } catch {}
}
// --- v937 — TvOverlay push (engine → bridge → TV; no VBA, no broker). The
// engine POSTs /tv/notify to this bridge and we forward it to the TvOverlay
// REST API at TV_OVERLAY_URL (e.g. http://192.168.11.50:5678). No-op if unset.
const TV_OVERLAY_URL = (process.env.TV_OVERLAY_URL || "").trim().replace(/\/+$/, "");
const TV_MQTT_TOPIC = (process.env.TV_MQTT_TOPIC || "").trim();   // topic TvOverlay subscribes to for commands (find via broker sniff / VBA broker subscribe log)
function tvOverlayPost(pathName, bodyObj, cb) {
    if (!TV_OVERLAY_URL) { if (cb) cb(new Error("TV_OVERLAY_URL not set")); return; }
    let u;
    try { u = new URL(TV_OVERLAY_URL + pathName); }
    catch (e) { if (cb) cb(e); return; }
    const body = Buffer.from(JSON.stringify(bodyObj || {}));
    const mod = u.protocol === "https:" ? require("https") : http;
    const reqOut = mod.request({
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname,
        method: "POST",
        headers: { "Content-Type": "application/json", "Content-Length": body.length },
    }, (resp) => { resp.resume(); if (cb) cb(null, resp.statusCode); });
    reqOut.on("error", (e) => { console.log(`[tvoverlay] POST ${pathName} failed: ${e.message}`); if (cb) cb(e); });
    reqOut.write(body); reqOut.end();
}
function tvNotifyBody(m) {
    const b = {};
    // Full TvOverlay field set (notify + fixed): pass through whatever the caller sends.
    const passStr = ["id", "title", "message", "source", "image", "video",
        "largeIcon", "smallIcon", "smallIconColor", "corner", "icon", "iconColor",
        "messageColor", "borderColor", "backgroundColor", "shape"];
    for (const k of passStr) if (m[k] != null) b[k] = String(m[k]);
    if (m.duration != null)   b.duration = Number(m.duration);
    if (m.expiration != null) b.expiration = m.expiration;   // epoch int, "1y2w3d", or seconds
    if (m.visible != null)    b.visible = !!m.visible;
    return b;
}
function tvMqttPublish(topic, bodyObj, cb) {
    const t = topic || TV_MQTT_TOPIC;
    if (!t) { if (cb) cb(new Error("TV_MQTT_TOPIC not set")); return; }
    if (!mqttClient || !mqttClient.connected) { if (cb) cb(new Error("MQTT broker not connected (set KPOP_MQTT)")); return; }
    try { mqttClient.publish(t, JSON.stringify(bodyObj || {}), {}, (err) => { if (cb) cb(err || null); }); }
    catch (e) { if (cb) cb(e); }
}
// --- v939 — Tasker dispatch (engine → bridge → Tasker on phone/Android VM).
// Stateless: the engine sends transport + creds + command; we relay. Supports the
// Tasker HTTP Request Server (LAN), Join, AutoRemote (cloud), and MQTT.
function httpJson(urlStr, method, bodyObj, cb) {
    let u;
    try { u = new URL(urlStr); } catch (e) { return cb(e); }
    const mod = u.protocol === "https:" ? require("https") : http;
    const body = bodyObj != null ? Buffer.from(JSON.stringify(bodyObj)) : null;
    const headers = {};
    if (body) { headers["Content-Type"] = "application/json"; headers["Content-Length"] = body.length; }
    const reqOut = mod.request({
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + (u.search || ""),
        method, headers,
    }, (resp) => { let d = ""; resp.on("data", c => d += c); resp.on("end", () => cb(null, resp.statusCode, d)); });
    reqOut.on("error", (e) => cb(e));
    if (body) reqOut.write(body);
    reqOut.end();
}
// v1555 - normalize a peer reference (full url, or bare ip[:port]) to an origin.
// A bare IP gets this engine's port appended so peers on the default 8787 just work.
function _peerBase(u) {
    u = String(u || "").trim().replace(/\/+$/, "");
    if (!u) return "";
    if (!/^https?:\/\//i.test(u)) u = "http://" + u;
    try { const x = new URL(u); if (!x.port) x.port = String(PORT); return x.origin; } catch { return ""; }
}
// v1555 - fetch JSON from a peer's own (ungated) routes with a hard timeout, so an
// unreachable peer can't hang the proxy. Returns parsed JSON or {ok:false,unreachable}.
function _peerJSON(base, pathPart, method, body, timeoutMs) {
    return new Promise((resolve) => {
        let u; try { u = new URL(base + pathPart); } catch (e) { resolve({ ok: false, error: "bad peer url" }); return; }
        const mod = u.protocol === "https:" ? require("https") : http;
        const payload = body != null ? Buffer.from(JSON.stringify(body)) : null;
        const headers = {}; if (payload) { headers["Content-Type"] = "application/json"; headers["Content-Length"] = payload.length; }
        let done = false; const fin = (v) => { if (!done) { done = true; resolve(v); } };
        const rq = mod.request({ hostname: u.hostname, port: u.port || (u.protocol === "https:" ? 443 : 80), path: u.pathname + (u.search || ""), method: method || "GET", headers }, (resp) => {
            let d = ""; resp.on("data", c => d += c); resp.on("end", () => { try { fin(JSON.parse(d || "{}")); } catch { fin({ ok: false, error: "bad json from peer", raw: String(d).slice(0, 160) }); } });
        });
        rq.on("error", (e) => fin({ ok: false, error: String((e && e.message) || e), unreachable: true }));
        rq.setTimeout(timeoutMs || 3500, () => { try { rq.destroy(); } catch {} fin({ ok: false, error: "peer timed out", unreachable: true }); });
        if (payload) rq.write(payload); rq.end();
    });
}
// v1555 - a peer is "running Home Assistant" if a VMware image whose name/path looks
// like HA is in its running list. Heuristic (name match) - flagged as such in the UI.
const _HA_NAME_RE = /home.?assist|haos|\bhass?\b/i;
function taskerDispatch(m, cb) {
    const transport = String(m.transport || "tasker_http");
    const command = String(m.command || m.message || "");
    const params = (m.params && typeof m.params === "object") ? m.params : {};
    if (transport === "tasker_http") {
        if (!m.httpUrl) return cb(new Error("no Tasker HTTP URL set"));
        httpJson(m.httpUrl, "POST", { command, params }, cb);
    } else if (transport === "join") {
        if (!m.joinKey || !m.joinDevice) return cb(new Error("Join needs joinKey + joinDevice"));
        const u = "https://joinjoaomgcd.appspot.com/_ah/api/messaging/v1/sendPush"
            + "?apikey=" + encodeURIComponent(m.joinKey)
            + "&deviceId=" + encodeURIComponent(m.joinDevice)
            + "&text=" + encodeURIComponent(command)
            + (m.title ? "&title=" + encodeURIComponent(m.title) : "");
        httpJson(u, "GET", null, cb);
    } else if (transport === "autoremote") {
        if (!m.autoremoteKey) return cb(new Error("AutoRemote needs autoremoteKey"));
        let msg = command;
        const ps = Object.values(params);
        if (ps.length) msg += "=:=" + ps.join("=:=");
        const u = "https://autoremotejoaomgcd.appspot.com/sendmessage?key="
            + encodeURIComponent(m.autoremoteKey) + "&message=" + encodeURIComponent(msg);
        httpJson(u, "GET", null, cb);
    } else if (transport === "mqtt") {
        const topic = m.mqttTopic || "";
        if (!topic) return cb(new Error("no MQTT topic set"));
        if (!mqttClient || !mqttClient.connected) return cb(new Error("MQTT not connected (set KPOP_MQTT)"));
        try { mqttClient.publish(topic, JSON.stringify({ command, params })); cb(null, 0); }
        catch (e) { cb(e); }
    } else {
        cb(new Error("unknown transport: " + transport));
    }
}
// v940 — Tasker R2 state (config + macro registry), cached + persisted so the
// PHONE can fire macros by id (it has no copy of the PC's localStorage). The PC
// pushes config+macros via POST /tasker/config; phone reads GET /tasker/state
// and fires POST /tasker/fire {id}.
const TASKER_STATE_FILE = path.join(__dirname, "tasker-state.json");
let taskerState = { config: {}, macros: [] };
try {
    if (fs.existsSync(TASKER_STATE_FILE)) {
        const j = JSON.parse(fs.readFileSync(TASKER_STATE_FILE, "utf8"));
        if (j && typeof j === "object") taskerState = { config: j.config || {}, macros: Array.isArray(j.macros) ? j.macros : [] };
    }
} catch {}
function saveTaskerState() {
    try { fs.writeFileSync(TASKER_STATE_FILE, JSON.stringify(taskerState)); return true; }
    catch { return false; }
}
// v948 — Generation scheduler queue. The BRIDGE holds the queue (persistent,
// any surface can add jobs); the PC ENGINE is the single drainer (it owns
// window.ai.generate, which makes a voxel asset via Gemini and auto-ingests it
// into the Universal Asset Library WITHOUT spawning — see main.js v800 wrap).
const GEN_QUEUE_FILE = path.join(__dirname, "gen-queue.json");
let genQueue = { paused: false, jobs: [], autoAvatar: false };
try {
    if (fs.existsSync(GEN_QUEUE_FILE)) {
        const j = JSON.parse(fs.readFileSync(GEN_QUEUE_FILE, "utf8"));
        if (j && typeof j === "object") genQueue = { paused: !!j.paused, jobs: Array.isArray(j.jobs) ? j.jobs : [], autoAvatar: !!j.autoAvatar };
    }
} catch (e) { console.warn("[gen-queue] load failed:", e.message); }
let _genJobSeq = genQueue.jobs.reduce((m, j) => Math.max(m, j._seq || 0), 0);
const GEN_STALE_MS = 5 * 60 * 1000;   // a 'running' job older than this is treated as an orphan and requeued
function saveGenQueue() {
    try { fs.writeFileSync(GEN_QUEUE_FILE, JSON.stringify(genQueue)); return true; }
    catch (e) { console.warn("[gen-queue] save failed:", e.message); return false; }
}
// v949 — spawn relay. A standalone library page (asset-library.html, possibly on
// a phone or the Android TV Device, or just another browser tab) can't reach
// window.spawnAssetFromLibrary inside the running engine, so it POSTs an asset id
// here; the engine polls /spawn/pending, which DRAINS this list, and spawns each.
// Drain semantics (not openUrl's latest-seq) so several quick spawns all arrive.
// Ephemeral on purpose — not persisted; a restart should not replay live spawns.
let spawnPending = [];
// v941 (R3) — INBOUND Tasker events (AutoNotification / AutoVoice / any Tasker task
// that POSTs /tasker/event). Ring buffer (cap 50), persisted. The engine polls
// GET /tasker/event and reacts on a new seq (mirrors the /open-url pattern).
const TASKER_EVENTS_FILE = path.join(__dirname, "tasker-events.json");
let taskerEvents = [];
try {
    if (fs.existsSync(TASKER_EVENTS_FILE)) {
        const j = JSON.parse(fs.readFileSync(TASKER_EVENTS_FILE, "utf8"));
        if (Array.isArray(j)) taskerEvents = j;
    }
} catch {}
let taskerEventSeq = taskerEvents.length ? (taskerEvents[taskerEvents.length - 1].seq || 0) : 0;
function pushTaskerEvent(ev) {
    taskerEventSeq++;
    const rec = {
        seq: taskerEventSeq,
        ts: Date.now(),
        kind:    ev && ev.kind    != null ? String(ev.kind)    : "event",
        command: ev && ev.command != null ? String(ev.command) : "",
        text:    ev && ev.text    != null ? String(ev.text)    : "",
        params:  (ev && ev.params && typeof ev.params === "object") ? ev.params : {},
        source:  ev && ev.source  != null ? String(ev.source)  : "",
        replyId: ev && ev.replyId != null ? String(ev.replyId) : "",   // v942 — round-trip correlation
    };
    taskerEvents.push(rec);
    if (taskerEvents.length > 50) taskerEvents = taskerEvents.slice(-50);
    try { fs.writeFileSync(TASKER_EVENTS_FILE, JSON.stringify(taskerEvents)); } catch {}
    return rec;
}
// v943 — Join direct push (engine→phone notification, distinct from triggering a
// Tasker command). Builds a Join sendPush URL; the route falls back to the
// Settings-configured Join creds when the body omits them.
function joinPushUrl(o) {
    const base = "https://joinjoaomgcd.appspot.com/_ah/api/messaging/v1/sendPush";
    const q = ["apikey=" + encodeURIComponent(o.apikey), "deviceId=" + encodeURIComponent(o.deviceId)];
    if (o.text)  q.push("text="  + encodeURIComponent(o.text));
    if (o.title) q.push("title=" + encodeURIComponent(o.title));
    if (o.url)   q.push("url="   + encodeURIComponent(o.url));
    if (o.icon)  q.push("icon="  + encodeURIComponent(o.icon));
    return base + "?" + q.join("&");
}
const USE_HTTPS = /^(1|true|yes|on)$/i.test(process.env.HTTPS || "");
function getCreds() {
    const dir = path.join(__dirname, "certs");
    const keyP = path.join(dir, "key.pem"), certP = path.join(dir, "cert.pem");
    try { if (fs.existsSync(keyP) && fs.existsSync(certP)) return { key: fs.readFileSync(keyP), cert: fs.readFileSync(certP) }; } catch {}
    try {
        const selfsigned = require("selfsigned");
        const pems = selfsigned.generate([{ name: "commonName", value: "voxelengine.local" }], { days: 3650, keySize: 2048 });
        try { fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(keyP, pems.private); fs.writeFileSync(certP, pems.cert); } catch {}
        console.log("[relay] generated a self-signed cert (ai-bridge/certs/)");
        return { key: pems.private, cert: pems.cert };
    } catch { return null; }
}

// Round 51 - VBA AI bridge state. The /bridge/* endpoints share this
