// dashboards. Lives in module scope so restarts wipe it (intentional;
// directives are ephemeral and shouldn't survive a server bounce).
const bridgeState = {
    latest: null,         // most recent game state from VBA
    lastTickMs: 0,
    totalTicks: 0,
    directives: [],       // FIFO; drained on game_tick
};

// Engine root = directory one level up from this file. That's the folder
