const _slowRoutes = new Map();
function _timeRequest(req, res) {
    const t0 = Date.now();
    const key = String(req.url || "").split("?")[0];
    res.once("finish", () => {
        const ms = Date.now() - t0;
        // v3276 -- 750ms MISSED EVERYTHING AND THAT WAS USEFUL EXACTLY ONCE. An empty table proved no handler
        // is pathological; it cannot show what a request actually COSTS, and "under 750ms" spans 5ms and 700ms
        // -- a 140x difference that decides whether twenty-six pollers fit in a pool at all. 250ms names the
        // merely-expensive without naming every cache read.
        if (ms < 250) return;
        const prev = _slowRoutes.get(key) || { max: 0, hits: 0, said: false };
        prev.hits++;
        if (ms > prev.max) { prev.max = ms; prev.said = false; }
        _slowRoutes.set(key, prev);
        if (!prev.said) {
            prev.said = true;
            console.log("[slow] " + key + " took " + ms + "ms (worst so far; " + prev.hits + " slow hit" +
                (prev.hits === 1 ? "" : "s") + "). While this runs, every other request on this box waits.");
        }
    });
}
// A route to read the whole picture at once, because a console scrolls and a table does not.
function _slowReport() {
    return { ok: true, thresholdMs: 250,
        routes: [..._slowRoutes.entries()].map(([route, v]) => ({ route, worstMs: v.max, slowHits: v.hits }))
            .sort((a, b) => b.worstMs - a.worstMs) };
}
// Marked from the request path rather than from a specific route, because server.html is reachable as "/" and
// as "/server.html" and a gate that knew only one of those would be a gate that sometimes is not there.
function _markPageServed(url) {
    if (_pageServedAt) return;
    const p = String(url || "").split("?")[0];
    if (p === "/" || p === "/server.html") {
        _pageServedAt = Date.now();
        console.log("[boot] server.html served after " + Math.round((_pageServedAt - _bootAt) / 1000) +
            "s -- startup work defers for a short grace while it loads.");
    }
}
let _pageSettledAt = 0, _pageServedAt = 0, _statsAsked = false;

// v3272 -- *** v3271 GATED ON A SIGNAL THAT NEVER ARRIVED, AND COST KEITH NINETY SECONDS FOR NOTHING. ***
// It waited for /system/stats -- the CPU gauge's own feed, which is the right marker for "fully loaded" and the
// WRONG ONE to gate on, because on his box THE PAGE NEVER GOT THERE INSIDE THE WINDOW. The fallback then ran the
// version check anyway, so the deferral bought a minute and a half of silence and changed nothing.
//
// THE GATE IS "THE PAGE IS LOADING" NOW, NOT "THE PAGE IS FINISHED": server.html being SERVED always happens, and
// it is the moment competing for the socket pool starts to hurt. A short grace after that covers the load itself.
// A SIGNAL THAT MIGHT NOT ARRIVE IS NOT A GATE, IT IS A TIMEOUT WEARING ONE.
const PAGE_GRACE_MS = 25000;
function _bootDeferReason() {
    if (_statsAsked) return null;                                   // gauges alive: definitely done
    if (!_pageServedAt) {
        // Nobody has even asked for the page. THAT IS NOT A REASON TO WAIT -- a headless box would wait forever,
        // and the old 90s blanket is exactly the "timeout wearing a gate" this replaces.
        return (Date.now() - _bootAt < 20000) ? "no page has been requested yet" : null;
    }
    const since = Date.now() - _pageServedAt;
    return since < PAGE_GRACE_MS ? "server.html is still loading (" + Math.round(since / 1000) + "s of " +
        Math.round(PAGE_GRACE_MS / 1000) + "s grace)" : null;
}

// v3247 -- INSTALL AND RUN HISTORY. Keith: "the swek engine could catch the extract and rerun start times on
// next run, and be able to display history for prior install and run times?" -- and it is the only thing that
// can. v3246 timed the update BUTTON and said plainly it loses the process at the restart; a MANUAL extract is
// invisible to a browser entirely, since nobody has the page open while they unzip. THE SERVER IS THE THING
// THAT COMES BACK, so it measures from the far side: process boot minus main.js mtime.
const _installHistory = require("./installHistory.js");
let _bootRecord = null;
try { _bootRecord = _installHistory.recordBoot(ENGINE_ROOT, ENGINE_VERSION_FOR_HISTORY()); } catch (e) { console.warn("[install-history]", e && e.message); }
// The heartbeat is what lets the NEXT boot say how long the gap was. Sixty seconds is coarse on purpose: this
// is a downtime figure, not a uptime monitor, and a file rewritten every second is a file nobody wants.
try { setInterval(() => { try { _installHistory.touch(ENGINE_ROOT); } catch {} }, 60000).unref(); } catch {}

function ENGINE_VERSION_FOR_HISTORY() {
    // READ FROM main.js RATHER THAN TYPED HERE -- a version constant in two files is the defect this project
    // has found nine times over, and the ship ritual already bumps that one.
    try {
        // v3809 -- ENGINE_ROOT is the WebGLEngine dir (resolve(__dirname,"..") from ai-bridge/), so main.js is
        // ENGINE_ROOT/main.js -- exactly what the two working callers _currentVersion() and the updater use via
        // path.join(__dirname, "..", "main.js"). The doubled ENGINE_ROOT/WebGLEngine/main.js here read a file
        // that does not exist, so this ALWAYS returned "?" and every install-history record was version "?".
        const src = fs.readFileSync(path.join(ENGINE_ROOT, "main.js"), "utf8");
        const m = src.match(/const ENGINE_VERSION = "([^"]+)"/);
        return m ? m[1] : "?";
    } catch { return "?"; }
}

