const KPOP_SENTINEL = path.join(os.tmpdir(), "KPopListener", "Listener_Alive.txt");
// v1570 — GPU name for /node/caps, primed async at boot + refreshed every 5 min so the polled
// capability endpoint never blocks on the detector.
//
// v3744 -- *** DETECTOR WAS NVIDIA-ONLY, SO EVERY NON-NVIDIA BOX REPORTED "NO GPU". *** nvidia-smi is absent on
// Macs (Metal) and on AMD/Intel Windows/Linux, so _capsGpu was "" on all of them and the engine said "GPU not
// found" for hardware that works fine. /install/gpu already detects Apple/AMD/Intel correctly; this brings the
// ALWAYS-ON caps path to parity. NVIDIA is still tried first (clean name + accel=cuda), so the Windows/NVIDIA
// box is byte-for-byte unchanged. Everything runs off the request path (primed at boot, refreshed 5-minutely),
// exactly as before, so a slow system_profiler/wmic can never block a poll.
let _capsGpu = "";          // GPU name, "" only when genuinely none
let _capsGpuAccel = "cpu";  // "cuda" | "rocm" | "metal" | "intel" | "amd" | "cpu"
function _capsGpuName() { return _capsGpu; }
function _capsGpuAccelName() { return _capsGpuAccel; }
// Detect a GPU NAME (not utilization) for THIS machine, cross-platform. cb(name, accel). name "" => none.
function _detectGpuName(cb) {
    const cp = require("child_process");
    const fin = (name, accel) => { try { cb((name || "").trim(), accel || (name ? "gpu" : "cpu")); } catch {} };
    // 1) NVIDIA first, on every platform that has nvidia-smi. Unchanged from v1570.
    try {
        cp.execFile("nvidia-smi", ["--query-gpu=name", "--format=csv,noheader"], { timeout: 4000 }, (err, stdout) => {
            const nm = (!err && stdout) ? (String(stdout).split(/\r?\n/)[0] || "").trim() : "";
            if (nm) return fin(nm, "cuda");
            // 2) No NVIDIA -> platform-specific detectors, mirroring /install/gpu.
            if (process.platform === "darwin") {
                // The real GPU chipset (Apple Silicon: "Apple M1 Pro"; Intel Mac: "Intel Iris Plus" / "AMD Radeon Pro …").
                cp.exec("system_profiler SPDisplaysDataType 2>/dev/null", { timeout: 6000 }, (e2, out2) => {
                    let chip = "";
                    const m = String(out2 || "").match(/Chipset Model:\s*(.+)/i);
                    if (m) chip = m[1].trim();
                    if (chip) { const a = /Apple/i.test(chip) ? "metal" : (/AMD|Radeon/i.test(chip) ? "amd" : (/Intel/i.test(chip) ? "intel" : "metal")); return fin(chip, a); }
                    // Fallback: the chip brand (Apple Silicon's GPU is the chip). Never leaves a Mac reading "no GPU".
                    cp.exec("sysctl -n machdep.cpu.brand_string 2>/dev/null", { timeout: 4000 }, (e3, out3) => {
                        const b = String(out3 || "").trim();
                        if (/Apple\s*M/i.test(b)) return fin(b + " GPU", "metal");
                        return fin(b ? (b + " (integrated)") : "Apple GPU", "metal");   // integrated GPU is still a GPU
                    });
                });
                return;
            }
            if (process.platform === "win32") {
                // AMD/Intel on Windows. wmic first (fast, present on most builds); PowerShell CIM as the fallback.
                cp.exec('wmic path win32_VideoController get name /value', { timeout: 6000 }, (e2, out2) => {
                    const names = String(out2 || "").split(/\r?\n/).map(l => (l.split("=")[1] || "").trim()).filter(Boolean);
                    const pick = names.find(n => /Radeon|RX |AMD|Arc |Intel|GeForce|RTX|Quadro/i.test(n)) || names[0] || "";
                    if (pick) return fin(pick, /Radeon|RX |AMD/i.test(pick) ? "amd" : /Arc |Intel/i.test(pick) ? "intel" : "gpu");
                    cp.exec('powershell -NoProfile -Command "(Get-CimInstance Win32_VideoController | Select-Object -First 1 -ExpandProperty Name)"', { timeout: 7000 }, (e3, out3) => {
                        const nm3 = String(out3 || "").trim();
                        return fin(nm3, /Radeon|RX |AMD/i.test(nm3) ? "amd" : /Arc |Intel/i.test(nm3) ? "intel" : (nm3 ? "gpu" : "cpu"));
                    });
                });
                return;
            }
            // Linux (non-NVIDIA): AMD/Intel via lspci.
            cp.exec("lspci 2>/dev/null | grep -Ei 'vga|3d|display'", { timeout: 5000 }, (e2, out2) => {
                const line = String(out2 || "").split(/\r?\n/).filter(Boolean)[0] || "";
                const nm = line.replace(/^.*controller:\s*/i, "").trim();
                if (nm) return fin(nm, /AMD|Radeon/i.test(nm) ? "amd" : /Intel/i.test(nm) ? "intel" : "gpu");
                return fin("", "cpu");
            });
        });
    } catch { fin("", "cpu"); }
}
