let cpuPrev = null;              // { idle: number, total: number, ts: number }
function sampleCpuPct() {
    let idleSum = 0, totalSum = 0;
    for (const c of os.cpus()) {
        const t = c.times;
        const tot = t.user + t.nice + t.sys + t.idle + t.irq;
        idleSum  += t.idle;
        totalSum += tot;
    }
    const now = Date.now();
    let utilPct = 0;
    if (cpuPrev) {
        const dIdle  = idleSum  - cpuPrev.idle;
        const dTotal = totalSum - cpuPrev.total;
        if (dTotal > 0) utilPct = Math.max(0, Math.min(100, Math.round(100 * (1 - dIdle / dTotal))));
    }
    cpuPrev = { idle: idleSum, total: totalSum, ts: now };
    return { utilPct, cores: os.cpus().length };
}

// Set by the WSS init below — fans out to every connected client.
// Round 129 — multiplayer player registry. Each connected client gets
// a unique playerId on connection; their state (name/color/position/
// driven kaiju) is tracked here. A 10Hz broadcast loop sends each
// client a snapshot of all OTHER players' positions so they can render
// ghost markers + name labels. State updates from clients arrive as
// "player:announce" (one-shot on connect) and "player:state" (10Hz).
const players = new Map();   // playerId → { name, color, pos, yaw, kaijuPos, drivingKaiju, lastUpdate }

// Round 131 — multiplayer arc round 35: shared OGRE HP pool. The
// server tracks a single canonical HP pool that ANY connected player
// can damage. Clients each run their own local OGRE simulation (the
// chassis moves and acts independently in each tab — that's still a
// solo experience) but damage events from each client are sent to
// the server, summed into the shared pool, and broadcast back. Every
// client's HUD shows the shared HP draining from cumulative damage,
// so two players hammering "their" OGRE actually see their combined
// effort. When shared HP hits zero, the server broadcasts a kill
// event; clients can display "team kill" credit by contributor.
const sharedOgre = {
    active: false,
    ogreHp:    0,
    ogreMaxHp: 0,
    wave:      0,
    startedAt: 0,
    contributors: new Map(),   // playerId → cumulative damage dealt

    // Round 148 (multiplayer round 36) — server-side canonical OGRE position.
    // Single shared position simulated on the server, broadcast at 10Hz.
    // Replaces the per-client local OGRE simulation: every connected
    // tab now sees the OGRE at the same coordinates.
    pos:       { x: 0, y: 0, z: 0 },
    vel:       { x: 0, y: 0, z: 0 },
    yaw:       0,
    targetId:  null,    // player ID currently being pursued
    lastTick:  0,
    spawnedAt: 0,

    // Round 156 — Option D mini-win #2: stuck detection.
    // _stuckCheckAt: when we last sampled position; _stuckRefX/Z:
    // position at last sample; _stuckTeleports: count of times we've
    // had to bail the OGRE out (logged so we can tune the WAD).
    _stuckCheckAt:   0,
    _stuckRefX:      0,
    _stuckRefZ:      0,
    _stuckTeleports: 0,
};

// Round 148 — OGRE tuning. Speed is units/sec, attack range is units.
// These mirror the local OGRE simulation values the clients used to
// run on their own — keeps the gameplay feel consistent.
const OGRE_SPEED        = 8.0;
const OGRE_TURN_RATE    = 1.8;   // rad/sec
const OGRE_ATTACK_RANGE = 6.0;
const OGRE_ATTACK_DAMAGE = 8;    // damage per attack tick to closest player
const OGRE_ATTACK_PERIOD = 1.2;  // seconds between attacks
const OGRE_RETARGET_PERIOD = 2.5; // pick a new target this often
// Round 156 — stuck-detection: if the OGRE moves less than this many
// units over STUCK_CHECK_MS, it's stuck. Teleport to a player start.
const OGRE_STUCK_CHECK_MS    = 3000;
const OGRE_STUCK_MIN_MOVE    = 0.5;
let lastOgreAttackAt   = 0;
let lastOgreRetargetAt = 0;
// v1463 — a grunt SQUAD rallies around the king (the OGRE). Server-authoritative
// positions; brains (workers) decide each grunt's behavior. With no workers the
// grunts just orbit the king (harmless). Drives the Battle Network panel's squad
// narrative (spread out / circle / GUARD THE KING / reinforcements).
let _squad = [];
function _ensureSquad() {
    if (!sharedOgre.active) { _squad = []; return; }
    if (!_squad.length) {
        const n = 5, kx = sharedOgre.pos.x, kz = sharedOgre.pos.z;
        for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; _squad.push({ id: "grunt" + (i + 1), x: kx + Math.cos(a) * 6, z: kz + Math.sin(a) * 6 }); }
        try { mpAiBrain.logEvent("wave", "Reinforcements! " + n + " grunts rally to the king", { n }); } catch {}
    }
}
function _squadDrift(dt) {
    const SPD = 6;   // grunt move speed (u/s)
    for (const g of _squad) {
        const it = mpAiBrain.intentFor(g.id);
        if (it && (it.moveX != null || it.moveZ != null)) {
            const mx = it.moveX || 0, mz = it.moveZ || 0, len = Math.hypot(mx, mz) || 1;   // brain-steered (boids) vector
            g.x += (mx / len) * SPD * dt; g.z += (mz / len) * SPD * dt;
        } else {
            let tx = sharedOgre.pos.x, tz = sharedOgre.pos.z;   // fallback: hold formation by the king / chase
            if (it && it.state !== "guard" && it.targetId && players.has(it.targetId) && players.get(it.targetId).pos) { const pp = players.get(it.targetId).pos; tx = pp.x; tz = pp.z; }
            const k = Math.min(1, dt * 1.5); g.x += (tx - g.x) * k; g.z += (tz - g.z) * k;
        }
        const dx = g.x - sharedOgre.pos.x, dz = g.z - sharedOgre.pos.z, d = Math.hypot(dx, dz);   // keep near the battlefield
        if (d > 22) { g.x = sharedOgre.pos.x + dx / d * 22; g.z = sharedOgre.pos.z + dz / d * 22; }
    }
}

