// Round 154 — Option A: WAD-level multiplayer. Bridge parses a Doom
// WAD at startup (or falls back to a procedural test arena), builds
// 3D geometry once, serves it to all WebGL clients, and uses the wall
// list for server-side OGRE collision so the OGRE pursues players
// through real corridors.
const wadGeom = require("./wadGeometry.cjs");
// Round 155 — Option B: Doom textures through the parallax pipeline.
// Decode the WAD's palette + a feature wall texture + a floor flat
// at startup. Served alongside geometry; the WebGL renderer applies
// them to walls/floors/ceilings and runs them through POM.
const wadTex  = require("./wadTextures.cjs");
let levelGeometry = null;              // populated at startup
let levelGeometryJSON = null;          // cached JSON form for HTTP serving
let levelMaps = [];                    // map names in the loaded WAD (for the room picker)
let levelWalls = [];                   // 2D collision walls
let levelPlayerStarts = [];            // for spawn placement
let levelTextures = null;              // { wall, floor, source } — round 155

function loadLevel(mapNameArg) {
    // Try a WAD file first if WAD_PATH env var is set or there's a
    // default file at ai-bridge/wads/freedoom1.wad. Otherwise fall
    // back to the procedural test arena so the system works without
    // external assets.
    const wadPath = process.env.WAD_PATH || path.join(__dirname, "wads/freedoom1.wad");
    const mapName = mapNameArg || process.env.WAD_MAP || null;
    let geom = null;
    let wad = null;
    // Re-parse to get both geometry AND textures from the same buffer
    try {
        if (fs.existsSync(wadPath)) {
            const buf = fs.readFileSync(wadPath);
            wad = wadGeom.parseWAD(buf);
            levelMaps = wad ? wad.maps.map(function (m) { return m.name; }) : [];
            if (wad) {
                const mn = mapName || wad.maps[0]?.name;
                if (mn) {
                    const map = wadGeom.extractMap(wad, mn);
                    if (map) {
                        geom = wadGeom.buildGeometry(map, wadGeom.DEFAULT_SCALE);
                        geom.info.source = wadPath;
                    }
                }
            }
        }
    } catch (e) {
        console.warn("[wad] parse error:", e?.message);
    }
    if (geom) {
        console.log(`[wad] loaded ${geom.name} from ${wadPath}: `
                  + `${geom.floorTriCount} floor + ${geom.ceilingTriCount} ceiling `
                  + `+ ${geom.wallTriCount} wall tris, ${geom.collisionWalls.length} walls`);
    } else {
        geom = wadGeom.buildFallback();
        console.log(`[wad] using fallback ${geom.name}: `
                  + `${geom.floorTriCount} floor + ${geom.ceilingTriCount} ceiling `
                  + `+ ${geom.wallTriCount} wall tris, ${geom.collisionWalls.length} walls`);
    }
    levelGeometry = geom;
    levelGeometryJSON = JSON.stringify(wadGeom.toJSON(geom));
    levelWalls = geom.collisionWalls;
    levelPlayerStarts = geom.playerStarts;

    // Round 155 — load textures. If we parsed a WAD, try to pull
    // feature textures from it; otherwise use procedural fallback.
    try {
        if (wad) {
            levelTextures = wadTex.selectFeatureTextures(wad);
            if (!levelTextures || (!levelTextures.wall && !levelTextures.floor)) {
                console.warn("[wad] no usable textures found in WAD; using fallback");
                levelTextures = wadTex.buildFallbackTextures();
            }
        } else {
            levelTextures = wadTex.buildFallbackTextures();
        }
        const wn = levelTextures.wall?.name  ?? "(none)";
        const fn = levelTextures.floor?.name ?? "(none)";
        console.log(`[wad] textures: wall=${wn} (${levelTextures.wall?.width}×${levelTextures.wall?.height}) `
                  + `· floor=${fn} (${levelTextures.floor?.width}×${levelTextures.floor?.height}) `
                  + `· source=${levelTextures.source}`);
    } catch (e) {
        console.warn("[wad] texture load failed; using procedural fallback:", e?.message);
        levelTextures = wadTex.buildFallbackTextures();
    }

    // Seed the OGRE spawn area inside the level bounds
    if (geom.bounds) {
        sharedOgre.pos.x = (geom.bounds.minX + geom.bounds.maxX) * 0.5;
        sharedOgre.pos.z = (geom.bounds.minZ + geom.bounds.maxZ) * 0.5;
    }
}
loadLevel();

