function broadcastToOthers(excludeWs, msg) {
    // v729 — respect _target field for per-client routing. When set,
    // send only to the client with matching _clientId (still excluding
    // sender to prevent message loops). Falls back to broadcast if
    // target is missing or unmatched.
    // v730 — stamp _origin with sender's clientId so receivers can filter
    // messages by source (the phone uses this for the "targeted engine"
    // feature — only process state from the selected target device).
    const target = msg && msg._target;
    const stamped = Object.assign({}, msg, {
        _origin: excludeWs?._clientId || null,
        _originRole: excludeWs?._clientRole || null,
    });
    if (target) {
        delete stamped._target;
        const payload = JSON.stringify(stamped);
        let sent = 0;
        for (const client of wss.clients) {
            if (client === excludeWs) continue;
            if (client.readyState !== 1) continue;
            if (client._clientId === target) {
                try { client.send(payload); sent++; } catch {}
            }
        }
        if (sent > 0) return;
        // Target not found among other clients — fall through to broadcast
        // so the command still has a chance of being executed.
        console.warn(`[route] target "${target}" not connected; broadcasting "${msg.type}" instead`);
    }
    const payload = JSON.stringify(stamped);
    for (const client of wss.clients) {
        if (client === excludeWs) continue;
        if (client.readyState === 1) client.send(payload);
    }
}
// v448 — broadcast to EVERY connected client (used by the Gemini
// commentator to push ai:commentary lines to all viewers/the engine).
// v448 — broadcast to EVERY connected client (used by the Gemini
// commentator to push ai:commentary lines to all viewers/the engine).
// v731 — accepts optional originClientId; when provided, stamps _origin
// so receivers can filter. Default null = system event (the phone's
// target filter passes these through unconditionally so e.g. kpop:speak:end
// reaches every avatar regardless of target).
function broadcastAll(msg, originClientId = null) {
    const stamped = Object.assign({}, msg, { _origin: originClientId });
    const payload = JSON.stringify(stamped);
    for (const client of wss.clients) {
        if (client.readyState === 1) { try { client.send(payload); } catch {} }
    }
}
// v742 — debug fanout. Sends a debug:line payload only to clients that
// subscribed via debug:subscribe. Used for engine console capture +
// Shield logcat tee + TV Remote status forwarding. The payload includes
// ts (server-stamped epoch ms) and src tag so the viewer can color/label.
// v743 — added 500-line ring buffer so newly-subscribed viewers can see
// recent history (since they may have missed lines while their tab was
// closed). Buffer is in-memory only; survives until bridge restart.
// v745 — disk-backed persistence. Each line gets appended to
// ai-bridge/debug.log (NDJSON, one JSON object per line). File rotates
// when it exceeds DEBUG_LOG_MAX_BYTES → debug.log.1 (single archive).
// On bridge boot, the last DEBUG_RING_MAX lines are read from disk into
// the in-memory ring so the first viewer after a restart sees pre-restart
// history. Writes are async fire-and-forget — broadcast path stays fast.
const DEBUG_RING_MAX = 500;
const DEBUG_LOG_PATH = path.join(__dirname, "debug.log");
const DEBUG_LOG_ARCHIVE = path.join(__dirname, "debug.log.1");
const DEBUG_LOG_MAX_BYTES = 5 * 1024 * 1024;   // 5 MB then rotate
const debugRing = [];
let debugDiskBytes = 0;       // tracked from boot; used to decide rotation
let debugAppendsSinceCheck = 0;

// Load up to DEBUG_RING_MAX recent lines from disk on boot. Reads the
// active log + the archive if active is smaller than the ring. Tails by
// reading the whole file (capped to ~5MB), splitting on newlines, and
// taking the last N entries. Each entry is parsed as JSON; bad lines
// are skipped. Fails silently if the file doesn't exist (first run).
function _loadDebugRingFromDisk() {
    try {
        const buffers = [];
        let totalLines = 0;
        for (const filePath of [DEBUG_LOG_ARCHIVE, DEBUG_LOG_PATH]) {
            try {
                if (!fs.existsSync(filePath)) continue;
                const stat = fs.statSync(filePath);
                if (filePath === DEBUG_LOG_PATH) debugDiskBytes = stat.size;
                // Cap read at the file size or 6MB, whichever is smaller
                const buf = fs.readFileSync(filePath, "utf8");
                buffers.push(buf);
            } catch (e) { /* unreadable — skip */ }
        }
        const allLines = buffers.join("\n").split("\n");
        for (const line of allLines) {
            if (!line.trim()) continue;
            try {
                const obj = JSON.parse(line);
                if (obj && typeof obj === "object" && obj.line) {
                    debugRing.push(obj);
                    if (debugRing.length > DEBUG_RING_MAX) debugRing.shift();
                    totalLines++;
                }
            } catch { /* skip malformed line */ }
        }
        if (totalLines > 0) {
            console.log(`[debug-log] loaded ${debugRing.length} ring entries from disk (${totalLines} total parsed; ${(debugDiskBytes/1024).toFixed(1)} KB active)`);
        }
    } catch (e) {
        console.warn(`[debug-log] disk load failed: ${e.message}`);
    }
}
_loadDebugRingFromDisk();

function _rotateDebugLogIfNeeded() {
    debugAppendsSinceCheck++;
    if (debugAppendsSinceCheck < 50) return;   // only check every ~50 appends
    debugAppendsSinceCheck = 0;
    try {
        if (debugDiskBytes < DEBUG_LOG_MAX_BYTES) return;
        // Rotate: rename active → archive (replacing previous archive)
        try { fs.unlinkSync(DEBUG_LOG_ARCHIVE); } catch {}
        try {
            fs.renameSync(DEBUG_LOG_PATH, DEBUG_LOG_ARCHIVE);
            debugDiskBytes = 0;
            console.log(`[debug-log] rotated → debug.log.1 (was ${(DEBUG_LOG_MAX_BYTES/1024/1024).toFixed(1)} MB)`);
        } catch (e) {
            console.warn(`[debug-log] rotation failed: ${e.message}`);
        }
    } catch { /* nothing */ }
}

function broadcastDebug(line) {
    const stamped = Object.assign({ ts: Date.now() }, line);
    // v743 — push into ring buffer (drop oldest if full)
    debugRing.push(stamped);
    if (debugRing.length > DEBUG_RING_MAX) debugRing.shift();
    // v745 — also persist to disk (async fire-and-forget; failures
    // logged via ORIGINAL console.warn so we don't recurse through the
    // bridge-stdout intercept)
    try {
        const serialized = JSON.stringify(stamped) + "\n";
        debugDiskBytes += Buffer.byteLength(serialized, "utf8");
        fs.appendFile(DEBUG_LOG_PATH, serialized, (err) => {
            if (err) { /* swallow — too noisy to log every failed write */ }
        });
        _rotateDebugLogIfNeeded();
    } catch { /* swallow */ }
    const payload = JSON.stringify({ type: "debug:line", ...stamped });
    for (const client of wss.clients) {
        if (client.readyState !== 1) continue;
        if (!client._debugSub) continue;
        try { client.send(payload); } catch {}
    }
}
// v729 — targeted send. If msg._target is set to a clientId, delivers only
// to that client (per-client routing for the phone's "Remote debug target"
// pulldown). If _target is missing/empty/unmatched, falls back to
// broadcastAll. Returns the number of clients the message reached.
function routeOrBroadcast(msg) {
    const target = msg && msg._target;
    if (!target) { broadcastAll(msg); return wss.clients.size; }
    // Strip _target before sending so receivers don't see internal field
    const out = Object.assign({}, msg); delete out._target;
    const payload = JSON.stringify(out);
    let sent = 0;
    for (const client of wss.clients) {
        if (client.readyState !== 1) continue;
        if (client._clientId === target) {
            try { client.send(payload); sent++; } catch {}
        }
    }
    if (sent === 0) {
        // Target wasn't found (maybe disconnected) — fall back to broadcast
        // so the command still has a chance of being honored.
        console.warn(`[route] target client "${target}" not found, broadcasting (${wss.clients.size} clients)`);
        broadcastAll(out);
        return wss.clients.size;
    }
    return sent;
}
