// v1332 — optional solar/battery -> avatar mood tie (gated by ha-solar.json "mood": true,
// set from the solar gauges panel). Battery-centric so it's sign-convention-safe; only
// touches avatarMood when the band changes, so it never spams. Falls back to production
// presence when there's no battery role.
let _solarMoodBand = "";
function solarMoodTick() {
    try {
        const cfg = haSolar.getConfig(); if (!cfg || !cfg.mood) return;
        const s = haSolar.latest(); if (!s || !s.available) return;
        const batt = s.roles.battery ? parseFloat(s.roles.battery.state) : NaN;
        const pwr = s.roles.power ? parseFloat(s.roles.power.state) : NaN;
        let mood = "support", reason = "running on solar", band = "ok";
        if (!isNaN(batt)) {
            if (batt < 15) { mood = "alarm"; band = "low"; reason = "home battery low (" + Math.round(batt) + "%)"; }
            else if (batt < 30) { mood = "souring"; band = "dip"; reason = "battery draining (" + Math.round(batt) + "%)"; }
            else { mood = "support"; band = "ok"; reason = "battery healthy (" + Math.round(batt) + "%)"; }
        } else if (!isNaN(pwr)) {
            if (pwr > 50) { mood = "support"; band = "ok"; reason = "panels producing"; }
            else { mood = "souring"; band = "dip"; reason = "no solar production right now"; }
        } else return;
        if (band !== _solarMoodBand) {
            _solarMoodBand = band;
            avatarMood.mood = mood; avatarMood.reason = reason; avatarMood.ts = Date.now();
            try { broadcast({ type: "avatar:mood", mood, reason }); } catch {}
        }
    } catch {}
}
