    if (headline) { const m = headline.match(hRe); kind = m[1].toLowerCase(); petType = cap(m[2]); petName = m[3].trim(); title = cap(kind) + " " + petType + " - " + petName; }
    const status = (kind === "reunited") ? "archived" : "new";
    let sexRaw = val("M/F") || val("Sex") || val("Gender"), sex = "";
    if (/^m/i.test(sexRaw)) sex = "Male"; else if (/^f/i.test(sexRaw)) sex = "Female";
    const reportId = val("Pet FBI Report ID") || val("Report ID");
    const location = val("Location Specifics") || val("Location") || val("State, Zip");
