// v2092 — PawBoost alert parser (label-on-line, value-on-next-line; summary in subject).
function parsePawBoostBoardEmail(raw) {
    const text = String(raw || "").replace(/\r/g, "");
    const lines = text.split("\n").map((l) => l.trim());
    const cap = (s) => String(s || "").charAt(0).toUpperCase() + String(s || "").slice(1).toLowerCase();
    const val = (label) => {
        const re = new RegExp("^" + label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*:?\\s*$", "i");
        for (let i = 0; i < lines.length; i++) { if (re.test(lines[i]) && i + 1 < lines.length) { const v = lines[i + 1].trim(); if (v) return v; } }
        return "";
    };
    let petName = "", petType = "", kind = "", loc = "", reportId = "";
    const subj = lines.find((l) => /have you seen .+\?/i.test(l)) || "";
    const m = subj.match(/have you seen\s+(.+?)\?\s*(lost|found|reunited)\s+(cat|dog|bird|rabbit|pet)\s+in\s+(.+?)\s*\(id:\s*(\d+)/i);
    if (m) { petName = m[1].trim(); kind = m[2].toLowerCase(); petType = cap(m[3]); loc = m[4].trim(); reportId = m[5]; }
    const name = val("Name") || petName, species = val("Species") || petType, sexRaw = val("Sex");
    const pbId = val("PawBoost ID") || reportId, locSeen = val("Location Last Seen") || loc;
    const landmark = val("Nearest Landmark") || val("Last seen near") || "";
    petType = cap(species || petType || "Pet"); if (!["Cat", "Dog", "Bird", "Rabbit"].includes(petType)) petType = "Other";
    let sex = ""; if (/^m/i.test(sexRaw)) sex = "Male"; else if (/^f/i.test(sexRaw)) sex = "Female";
    const status = /reunited/i.test(text) ? "archived" : "new";
    const finalName = name || petName || "Unknown"; kind = kind || "lost";
    const title = cap(kind) + " " + petType + " - " + finalName;
    let link = ""; const u = text.match(/https?:\/\/(?:www\.)?pawboost\.com\/[^\s"'<>]+/i); if (u) link = u[0];
    return { ok: !!(finalName && (pbId || reportId)), source: "pawboost", title, petType, sex, status, reportId: String(pbId || reportId), location: locSeen, landmark, link, kind, petName: finalName };
}

