// v1309 — watering session: an engine-owned countdown representing "a zone is running for N
// seconds". Drives the avatar water-fill visual and auto-closes the valve when time's up. Works
// as a pure timer even without HA; if entity_id is given it also opens (now) and closes (at end)
// the HA valve. One session at a time (a new start replaces the old).
let _water = { active: false, startedAt: 0, durationMs: 0, zone: null, entity: null, timer: null };
function waterStatus() {
    if (!_water.active) return { ok: true, active: false, fraction: 0, remainingSec: 0, durationSec: 0, zone: null };
    const el = Date.now() - _water.startedAt;
    const fraction = _water.durationMs > 0 ? Math.max(0, Math.min(1, el / _water.durationMs)) : 0;
    const remainingSec = Math.max(0, Math.ceil((_water.durationMs - el) / 1000));
    return { ok: true, active: true, fraction, remainingSec, durationSec: Math.round(_water.durationMs / 1000), zone: _water.zone, startedAt: _water.startedAt };
}
function waterStop(closeValve) {
    if (_water.timer) { try { clearTimeout(_water.timer); } catch {} }
    if (closeValve && _water.entity) { try { haBridge.callService("valve", "close_valve", { entity_id: _water.entity }); } catch {} }
    _water = { active: false, startedAt: 0, durationMs: 0, zone: null, entity: null, timer: null };
    try { broadcast({ type: "water:level", active: false, fraction: 0, remainingSec: 0, durationSec: 0 }); } catch {}
}
function waterStart(seconds, zone, entityId) {
    seconds = Math.max(1, Math.min(3600, parseInt(seconds, 10) || 30));
    if (_water.timer) { try { clearTimeout(_water.timer); } catch {} }
    _water = { active: true, startedAt: Date.now(), durationMs: seconds * 1000, zone: zone || entityId || "watering", entity: entityId || null, timer: null };
    if (entityId) { try { haBridge.callService("valve", "open_valve", { entity_id: entityId }); } catch {} }
    _water.timer = setTimeout(() => waterStop(true), seconds * 1000);
    try { broadcast({ type: "water:level", active: true, fraction: 0, remainingSec: seconds, durationSec: seconds, zone: _water.zone }); } catch {}
    return waterStatus();
}
