function isPidAlive(pid) {
    if (!pid) return false;
    try {
        // signal 0 doesn't actually send a signal — it just probes
        // for permission/existence. Throws ESRCH if the process is
        // gone, EPERM if alive but inaccessible (rare for our own
        // child). EPERM still means it's alive.
        process.kill(pid, 0);
        return true;
    } catch (e) {
        return e.code === "EPERM";
    }
}

// Round 91 — variants persistence file. Holds LLM-generated runtime
// variant definitions + the failed-OBJ name list, so they survive page
// reloads. Atomic writes via tmp+rename. Read returns {variants, failed}
// with sensible defaults if the file is missing/corrupt.
const VARIANTS_FILE = path.join(ENGINE_ROOT, "variants_persistent.json");
function readVariantsFile() {
    try {
        if (!fs.existsSync(VARIANTS_FILE)) return { variants: [], failed: [] };
        const text = fs.readFileSync(VARIANTS_FILE, "utf-8");
        const j = JSON.parse(text);
        if (!j || typeof j !== "object") return { variants: [], failed: [] };
        return {
            variants: Array.isArray(j.variants) ? j.variants : [],
            failed:   Array.isArray(j.failed)   ? j.failed   : [],
        };
    } catch {
        return { variants: [], failed: [] };
    }
}
function writeVariantsFile(data) {
    try {
        const text = JSON.stringify(data, null, 2);
        const tmp = VARIANTS_FILE + ".tmp";
        fs.writeFileSync(tmp, text, "utf-8");
        fs.renameSync(tmp, VARIANTS_FILE);
    } catch (e) {
        console.warn("[variants] write failed:", e.message);
    }
}

