// ===========================================================================
// Round 339 — INSTALL_CATALOG
//
// Server-side mirror of the front-end install panel catalog. The browser
// asks /install/exec to run an item BY ID, and the bridge looks the
// commands up here. This means:
//   - The browser never gets to inject raw shell strings
//   - The user can review/edit this file once, then run safely from the UI
//   - A page that gets compromised can't run anything not in this list
//
// v347 — externalized to ai-bridge/install_catalog.json so the user can
// edit install commands as a text file without restarting Node. The file
// is re-read on every /install/exec call. mtime-based caching avoids
// disk I/O when nothing changed. If the file is missing or invalid, the
// bridge falls back to an empty catalog and logs the error.
// ===========================================================================

const INSTALL_CATALOG_PATH = path.join(__dirname, "install_catalog.json");
let _installCatalogCache = null;
let _installCatalogMtime = 0;
let _installCatalogLastError = null;

function loadInstallCatalog() {
    try {
        const st = fs.statSync(INSTALL_CATALOG_PATH);
        if (_installCatalogCache && st.mtimeMs === _installCatalogMtime) {
            return _installCatalogCache;   // unchanged, return cached
        }
        const text = fs.readFileSync(INSTALL_CATALOG_PATH, "utf8");
        const parsed = JSON.parse(text);
        // Strip metadata keys (anything starting with _)
        const catalog = {};
        for (const [k, v] of Object.entries(parsed)) {
            if (!k.startsWith("_")) catalog[k] = v;
        }
        _installCatalogCache = catalog;
        _installCatalogMtime = st.mtimeMs;
        _installCatalogLastError = null;
        return catalog;
    } catch (e) {
        _installCatalogLastError = e.message;
        if (_installCatalogCache) {
            console.warn(`[install_catalog] read failed (${e.message}); serving last good cache`);
            return _installCatalogCache;
        }
        console.warn(`[install_catalog] read failed (${e.message}); using empty catalog`);
        return {};
    }
}

// Initial load at startup so we log any catalog errors early
loadInstallCatalog();
if (_installCatalogLastError) {
    console.warn(`[install_catalog] startup load error: ${_installCatalogLastError}`);
} else {
    console.log(`[install_catalog] loaded ${Object.keys(_installCatalogCache).length} entries from ${INSTALL_CATALOG_PATH}`);
}

// ===========================================================================
// v470 — filesystem verification for the install panel.
//
// The panel's node/python/model rows used to be MANUAL "mark installed"
// checkboxes saved only in the browser's localStorage. When that got cleared
// (data wipe / different profile) everything reverted to "missing" even though
// nothing changed on disk. These helpers let the bridge — which can actually
// stat the filesystem — report the true state. We derive each item's check
// target straight from its catalog `cmds` (no per-entry hand-maintenance):
//   node-*   → custom_nodes/<folder> exists   (folder from Test-Path / clone)
//   py-*     → package present in pip list     (names parsed from pip install)
//   model-*  → only if the entry carries an explicit checkPath
//   patch-*  → never auto-checkable (they're edits inside files) → "unknown"
// "unknown" is deliberately distinct from "missing": we only say missing when
// we positively verified absence.
// ===========================================================================
// v560 — size measurement for the install panel. Cached by path+mtime+size
// signature so repeated /install/size calls are cheap. Capped (file count +
// wall-clock deadline) so a huge tree can't hang the bridge.
let _sizeCache = new Map();
function _dirSize(p) {
    const cap = { files: 80000, deadlineMs: Date.now() + 4000 };
    let bytes = 0, files = 0, truncated = false;
    const stack = [p];
    while (stack.length) {
        if (files > cap.files || Date.now() > cap.deadlineMs) { truncated = true; break; }
        const cur = stack.pop();
        let st;
        try { st = fs.lstatSync(cur); } catch { continue; }
        if (st.isSymbolicLink()) continue;
        if (st.isDirectory()) {
            let ents = [];
            try { ents = fs.readdirSync(cur); } catch { continue; }
            for (const e of ents) stack.push(path.join(cur, e));
        } else if (st.isFile()) {
            bytes += st.size; files++;
        }
    }
    return { bytes, files, truncated };
}

