function loadAuth() { try { if (fs.existsSync(AUTH_CFG)) return JSON.parse(fs.readFileSync(AUTH_CFG, "utf8")); } catch {} return null; }
function saveAuth(o) { try { fs.mkdirSync(path.dirname(AUTH_CFG), { recursive: true }); fs.writeFileSync(AUTH_CFG, JSON.stringify(o), { mode: 0o600 }); return true; } catch (e) { console.warn("[auth] save failed:", e.message); return false; } }
