const _ownIPs = (() => { const s = new Set(["127.0.0.1", "::1"]); try { const ifs = os.networkInterfaces(); for (const name of Object.keys(ifs)) for (const ni of (ifs[name] || [])) if (ni && ni.address) s.add(String(ni.address).replace(/^::ffff:/, "")); } catch {} return s; })();
