// --- SweK internal chat (LAN-local, box-to-box direct; no cloud relay needed) ---
let _chatLog = [];          // ring of { id, from, fromName, text, ts, scope, to? }  scope: "in" (received) | "out" (sent)
let _chatSeq = 0;

// v1777 — chat file blob store. Files are base64-POSTed here, stored in-memory with a TTL, served to LAN peers
// via GET /swek/chat/blob/<id>. When rendezvous is live, the relay route uploads to cloudLink.uploadBlob() instead
// so cross-NAT recipients can fetch from the cloud URL. Caps: 8 MB/file, 50 MB total, 30 min TTL.
const _BLOB_FILE_MAX  = 8  * 1024 * 1024;   // 8 MB per file (base64 decoded)
