    // v707 — /shield/notifications. Receives notifications captured by
    // Tasker + AutoNotification on the user's phone, stores the last N
    // in a small JSON file, surfaces them to the phone control panel so
    // the user can re-fire a captured deep-link intent on the Android TV Device via
    // ADB (`am start -d <intent>`).
    //
    // POST body (from Tasker AutoNotification Intercept event):
    //   {
    //     app:       "Blink Home Monitor"     // package label, free-form
    //     title:     "Motion at Front Door"   // notification title
    //     text:      "..."                    // notification body
    //     intentUri: "blinkapp://camera/123"  // %antitle / %anintent.uri
    //     extras:    "..."                    // optional, raw extras dump
    //     ts:        1717182000               // optional, defaults to now
    //   }
    // No auth gate by default — designed for LAN-only use. Bind the bridge
    // to localhost or your LAN interface only, not 0.0.0.0 on the public
    // internet.
    //
    // GET returns: { items: [{ ts, app, title, text, intentUri, ... }, ...] }
    //              newest-first, capped at N items.
    if (req.method === "POST" && req.url === "/shield/notifications") {
        let body = "";
        req.on("data", c => { body += c; if (body.length > 32768) req.destroy(); });   // hard cap 32KB
        req.on("end", () => {
            const reply = (obj, code = 200) => {
                res.writeHead(code, { "Content-Type": "application/json" });
                res.end(JSON.stringify(obj));
            };
            let j;
            try { j = body ? JSON.parse(body) : {}; }
            catch { return reply({ ok: false, error: "bad JSON" }, 400); }
            // Validate + clamp string lengths
            const clean = {
                ts:        parseInt(j.ts, 10) || Date.now(),
                app:       String(j.app || "").slice(0, 80),
                title:     String(j.title || "").slice(0, 200),
                text:      String(j.text || "").slice(0, 500),
                intentUri: String(j.intentUri || "").slice(0, 500),
                extras:    String(j.extras || "").slice(0, 2000),
            };
            // Load + append + cap + save
            const NOTIF_FILE = path.join(__dirname, "shield-notifications.json");
            const MAX_KEEP = 50;
            let items = [];
            try {
                if (fs.existsSync(NOTIF_FILE)) {
                    items = JSON.parse(fs.readFileSync(NOTIF_FILE, "utf8"));
                    if (!Array.isArray(items)) items = [];
                }
            } catch {}
            items.unshift(clean);
            if (items.length > MAX_KEEP) items.length = MAX_KEEP;
            try { fs.writeFileSync(NOTIF_FILE, JSON.stringify(items)); }
            catch (e) { return reply({ ok: false, error: "write failed: " + e.message }, 500); }
            reply({ ok: true, stored: clean, total: items.length });
        });
        return;
    }
    if (req.method === "GET" && req.url === "/shield/notifications") {
        const NOTIF_FILE = path.join(__dirname, "shield-notifications.json");
        let items = [];
        try {
            if (fs.existsSync(NOTIF_FILE)) {
                items = JSON.parse(fs.readFileSync(NOTIF_FILE, "utf8"));
                if (!Array.isArray(items)) items = [];
            }
        } catch {}
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ items }));
        return;
    }
    if (req.method === "DELETE" && req.url === "/shield/notifications") {
        const NOTIF_FILE = path.join(__dirname, "shield-notifications.json");
        try { fs.unlinkSync(NOTIF_FILE); } catch {}
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ ok: true }));
        return;
    }
    // v710 — Discord webhook config + test endpoints. Reads/writes the
    // DISCORD_WEBHOOK_URL=... line in "KPop Listener/Credentials.bas"
    // (same file KPopListener.ps1's v709 import block reads from). Test
    // endpoint POSTs a sample embed to either the typed URL or the saved
    // one. Both are designed for LAN-only use — same auth assumptions as
    // /shield/notifications.
    //
    // The Credentials.bas path resolves UPWARD from ai-bridge/ to the
    // "KPop Listener" sibling directory.
    function _credentialsPath() {
        const candidates = [
            path.join(__dirname, "..", "..", "KPop Listener", "Credentials.bas"),
            path.join(__dirname, "..", "KPop Listener", "Credentials.bas"),
            path.join(__dirname, "..", "..", "..", "KPop Listener", "Credentials.bas"),
        ];
        for (const c of candidates) {
            try { if (fs.existsSync(path.dirname(c))) return c; } catch {}
        }
        // Fallback: create alongside ai-bridge if KPop Listener dir not found
        return path.join(__dirname, "Credentials.bas");
    }
    function _readWebhookFromCredentials() {
        try {
            const p = _credentialsPath();
            if (!fs.existsSync(p)) return null;
            const txt = fs.readFileSync(p, "utf8");
            const m = txt.match(/^\s*DISCORD_WEBHOOK_URL\s*=\s*(.+?)\s*$/m);
            return m ? m[1].trim() : null;
        } catch { return null; }
    }
    function _writeWebhookToCredentials(url) {
        const p = _credentialsPath();
        let txt = "";
        try { if (fs.existsSync(p)) txt = fs.readFileSync(p, "utf8"); } catch {}
        // Strip any existing DISCORD_WEBHOOK_URL line, then append (or
        // remove entirely if url is null)
        const lines = txt.split(/\r?\n/).filter(l => !/^\s*DISCORD_WEBHOOK_URL\s*=/.test(l));
        if (url) lines.push("DISCORD_WEBHOOK_URL=" + url);
        // Strip trailing empties
        while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
        const out = lines.join("\r\n") + (lines.length ? "\r\n" : "");
        fs.writeFileSync(p, out, "utf8");
        return p;
    }
    // v740 — solar values cached by haSolar.js. Returns { available, stale,
