    if (req.url.split("?")[0] === "/devbrowser/status") { devBrowserBridge.status().then(sendJson).catch(e => sendJson({ ok: false, error: String(e && e.message || e) })); return; }
    if (req.method === "GET" && req.url === "/devbrowser/config") { sendJson(devBrowserBridge.getConfig()); return; }
    if (req.method === "POST" && req.url === "/devbrowser/config") { if (!(_isTrustedReq(req))) { sendJson({ ok: false, error: "local only" }, 403); return; } readJson(d => sendJson(devBrowserBridge.setConfig(d || {}))); return; }
    if (req.method === "POST" && req.url === "/devbrowser/install") { if (!(_isTrustedReq(req))) { sendJson({ ok: false, error: "local only" }, 403); return; } devBrowserBridge.install().then(sendJson).catch(e => sendJson({ ok: false, error: String(e && e.message || e) })); return; }
    if (req.method === "POST" && req.url === "/devbrowser/run") { if (!(_isTrustedReq(req))) { sendJson({ ok: false, error: "local only" }, 403); return; } readJson(d => devBrowserBridge.runScript((d || {}).script, d || {}).then(sendJson).catch(e => sendJson({ ok: false, error: String(e && e.message || e) }))); return; }

    if (req.url.split("?")[0] === "/humanizer/status") { humanizerBridge.status(_ollamaBase()).then(sendJson).catch(e => sendJson({ ok: false, error: String(e && e.message || e) })); return; }
    if (req.method === "GET" && req.url === "/humanizer/config") { sendJson(humanizerBridge.getConfig()); return; }
    if (req.method === "POST" && req.url === "/humanizer/config") { if (!(_isTrustedReq(req))) { sendJson({ ok: false, error: "local only" }, 403); return; } readJson(d => sendJson(humanizerBridge.setConfig(d || {}))); return; }
    if (req.method === "POST" && req.url === "/humanizer/install") { if (!(_isTrustedReq(req))) { sendJson({ ok: false, error: "local only" }, 403); return; } humanizerBridge.install().then(sendJson).catch(e => sendJson({ ok: false, error: String(e && e.message || e) })); return; }
    if (req.method === "POST" && req.url === "/humanizer/humanize") { readJson(d => humanizerBridge.humanize(Object.assign({}, d || {}, { ollamaBase: _ollamaBase() })).then(sendJson).catch(e => sendJson({ ok: false, error: String(e && e.message || e) }))); return; }

    // ---- v1554 KPop listener crash file (written by KPopListener.ps1's trap) ----
    if (req.method === "GET" && req.url.split("?")[0] === "/kpop/crash") {
        try {
            const dir = path.join(os.tmpdir(), "KPopLogs");
            const crashF = path.join(dir, "KPop_last_crash.txt");
            let crash = null, crashAt = 0;
            if (fs.existsSync(crashF)) { crash = fs.readFileSync(crashF, "utf8").slice(-4000); try { crashAt = fs.statSync(crashF).mtimeMs; } catch {} }
            let logName = null, logTail = null;
            try { const logs = fs.readdirSync(dir).filter(f => /^KPop_.*\.log$/i.test(f)).map(f => ({ f, m: (() => { try { return fs.statSync(path.join(dir, f)).mtimeMs; } catch { return 0; } })() })).sort((a, b) => b.m - a.m); if (logs.length) { logName = logs[0].f; logTail = fs.readFileSync(path.join(dir, logs[0].f), "utf8").slice(-3000); } } catch {}
            sendJson({ ok: true, dir, crash, crashAt, logName, logTail });
        } catch (e) { sendJson({ ok: false, error: String((e && e.message) || e) }); }
        return;
    }

    // ---- v1555 peer VM/HA proxy ----------------------------------------------
    // Let server.html list peers, see at a glance whether a peer is running VMware /
    // Home Assistant, click through to a peer's server.html, and start/stop that peer's
    // VMs. This node fetches the peer's OWN /net/info + /vm/* routes (already ungated)
    // and relays them, so the browser never makes a cross-origin call. Same LAN-trust
    // model as the direct /vm/* routes (no extra auth on top).
    // v1570 — node capabilities a peer can advertise: Model Sync (asset auto-sync), CPU share
    // (act as an AI worker), available IP cameras (count), and GPU (name/availability). Served by
    // every bridge so server.html can show what each LAN peer is offering.
    // v1744 - capability proxy SERVE side: a trusted/LAN peer asks this box to run a whitelisted capability with THIS box's
    // own credential. The credential never leaves here; only the result is returned. Whitelist-gated + trusted-only.
    if (req.method === "POST" && req.url.split("?")[0] === "/cap/run") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson(async (d) => {
            const cap = String((d && d.capability) || "");
            const args = (d && typeof d.args === "object" && d.args) || {};
            if (!capabilityProxy.canServe(cap, _selfProxyCaps())) { sendJson({ ok: false, error: "this box cannot serve '" + cap + "'" }); return; }
            if (cap === "text2voxel") {
                const key = geminiCommentator.getKey() || (process.env.GEMINI_API_KEY || "").trim();
                try { const out = await generateAsset(key, String(args.prompt || ""), args.opts || {}); sendJson(out); }
                catch (e) { sendJson({ ok: false, error: String((e && e.message) || e) }, 500); }
                return;
            }
            if (cap === "ha") {
                const domain = String(args.domain || ""), service = String(args.service || ""), data = (args.data && typeof args.data === "object") ? args.data : {};
                if (!capabilityProxy.haDomainAllowed(domain)) { sendJson({ ok: false, error: "HA domain '" + domain + "' is not allowed via the proxy (allowed: " + capabilityProxy.HA_ALLOWED_DOMAINS.join(", ") + ")" }); return; }
                try { const r = await haBridge.callService(domain, service, data); sendJson(r && typeof r === "object" ? Object.assign({ ok: true }, r) : { ok: true }); }
                catch (e) { sendJson({ ok: false, error: String((e && e.message) || e) }, 500); }
                return;
            }
            sendJson({ ok: false, error: "unhandled capability" });
        });
        return;
    }
    // ===== v1752 - text2voxel request PIPELINE (queue visible to both ends + the network) ===========================
    if (req.method === "POST" && req.url.split("?")[0] === "/cap/queue/submit") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson((d) => {
            const cap = String((d && (d.cap || d.capability)) || "text2voxel");
            if (!capabilityProxy.canServe(cap, _selfProxyCaps())) { sendJson({ ok: false, error: "this box cannot serve '" + cap + "'" }); return; }
            const prompt = String((d && (d.prompt || (d.args && d.args.prompt))) || "").trim();
            if (!prompt) { sendJson({ ok: false, error: "prompt required" }); return; }
            const job = _capQ.enqueue({ cap, prompt, requesterId: (d && d.requesterId), requesterName: (d && d.requesterName) });
            console.log("[pipeline] queued " + job.id + " (" + cap + ") from " + job.requesterName + ": " + job.prompt.slice(0, 60));
            sendJson({ ok: true, id: job.id, status: job.status, position: _capQ.queuePosition(job.id) });
        });
        return;
    }
    if (req.method === "GET" && req.url.split("?")[0] === "/cap/queue") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        sendJson({ ok: true, serves: _selfProxyCaps(), stats: _capQ.stats(), policy: _capPolicy, jobs: _capQ.list() });
        return;
    }
    if (req.method === "GET" && req.url.split("?")[0] === "/cap/queue/result") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        const id = decodeURIComponent((req.url.split("id=")[1] || "").split("&")[0] || "");
        const j = _capQ.get(id); if (!j) { sendJson({ ok: false, error: "no such job" }, 404); return; }
        sendJson({ ok: true, id: j.id, status: j.status, result: (j.status === "done" ? j.result : null), error: j.error || "" });
        return;
    }
    if (req.method === "POST" && req.url.split("?")[0] === "/cap/queue/cancel") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson((d) => {
            const id = String((d && d.id) || ""), reqId = (d && d.requesterId) ? String(d.requesterId) : null, local = _isLocalReq(req);
            let r;
            if (local) r = _capQ.cancel(id, null);                                    // the owner manages its own queue
            else if (_capPolicy.requesterOnlyCancel) {                                // remote, restricted to own jobs
                if (!reqId) { sendJson({ ok: false, error: "this provider only lets a requester cancel its own jobs (requester id required)" }); return; }
                r = _capQ.cancel(id, reqId);
            } else r = _capQ.cancel(id, null);                                         // remote, unrestricted (default)
            sendJson(r && r.ok ? { ok: true, id: id, status: "canceled" } : { ok: false, error: (r && r.reason) || "cancel failed" });
        });
        return;
    }
    // v1755 - the provider (local only) sets whether remote requesters are limited to canceling their own jobs
    if (req.method === "POST" && req.url.split("?")[0] === "/cap/queue/policy") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        if (!_isLocalReq(req)) { sendJson({ ok: false, error: "only the provider (local) can set its pipeline policy" }, 403); return; }
        readJson((d) => { if (d && typeof d.requesterOnlyCancel === "boolean") _capPolicy.requesterOnlyCancel = d.requesterOnlyCancel; console.log("[pipeline] policy requesterOnlyCancel=" + _capPolicy.requesterOnlyCancel); sendJson({ ok: true, policy: _capPolicy }); });
        return;
    }
    if (req.method === "POST" && req.url.split("?")[0] === "/cap/queue/reorder") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson((d) => { const r = _capQ.reorder((d && Array.isArray(d.order)) ? d.order : []); sendJson(r && r.ok ? { ok: true, jobs: _capQ.list() } : { ok: false, error: "reorder failed" }); });
        return;
    }
    // ===== v1745 - deliberate, password-gated encrypted key MOVE =====================================================
    // A peer QUEUES a request (no key released yet). The holder's UI lists pending requests, the holder types their LOGIN
    // password to authorize, and only then is the secret sealed to the requester's published key and handed back. The
    // secret never leaves this box in plaintext; it is decrypted only in the requester's browser.
    if (req.method === "POST" && req.url.split("?")[0] === "/key/request") {
        readJson((d) => {
            const keyName = String((d && d.keyName) || "");
            if (!keyTransfer.keyEligible(keyName)) { sendJson({ ok: false, error: "'" + keyName + "' is not a transferable key" }); return; }
            if (!_readSecret(keyName)) { sendJson({ ok: false, error: "this box does not hold '" + keyName + "'" }); return; }
            const r = _newKeyReq({ keyName, requesterId: String((d && d.requesterId) || "").slice(0, 80), requesterName: String((d && d.requesterName) || "a peer").slice(0, 40), requesterUrl: String((d && d.requesterUrl) || "").slice(0, 200) });
            console.log("[keymove] request " + r.id + ": " + r.requesterName + " wants '" + keyName + "'");
            sendJson({ ok: true, id: r.id, status: "pending" });
        });
        return;
    }
    if (req.method === "GET" && req.url.split("?")[0] === "/key/requests") {   // holder UI (local) lists pending
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        sendJson({ ok: true, requests: [..._keyRequests.values()].filter(r => r.status === "pending").map(r => ({ id: r.id, keyName: r.keyName, requesterName: r.requesterName, requesterUrl: r.requesterUrl, ts: r.ts })) });
        return;
    }
    if (req.method === "POST" && req.url.split("?")[0] === "/key/approve") {   // holder authorizes with LOGIN password (gate 2)
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson(async (d) => {
            const r = _keyRequests.get(String((d && d.id) || ""));
            if (!r) { sendJson({ ok: false, error: "no such request" }); return; }
            if (r.status !== "pending") { sendJson({ ok: false, error: "already " + r.status }); return; }
            if (d && d.approve === false) { r.status = "denied"; console.log("[keymove] DENIED " + r.id); sendJson({ ok: true, status: "denied" }); return; }
            if (!authEnabled()) { sendJson({ ok: false, error: "set a login password first (Cloud & Hosting > Security) before approving key transfers" }); return; }
            if (!verifyPw(String((d && d.password) || ""))) { console.log("[keymove] wrong password for " + r.id); sendJson({ ok: false, error: "wrong password" }, 401); return; }
            const secret = _readSecret(r.keyName);
            if (!secret) { r.status = "denied"; sendJson({ ok: false, error: "key no longer present" }); return; }
            let pub = null; try { const ni = await _peerJSON(_peerBase(r.requesterUrl), "/net/info", "GET", null, 4000); pub = ni && ni.pubkey && (ni.pubkey.publicJwk || (ni.pubkey.kty ? ni.pubkey : null)); } catch {}
            if (!pub) { sendJson({ ok: false, error: "could not fetch the requester's public key (is " + r.requesterUrl + " reachable?)" }); return; }
            try { const m = await _swekCrypto(); r.envelope = await m.seal(pub, secret); r.status = "approved"; console.log("[keymove] APPROVED " + r.id + " - sealed '" + r.keyName + "' to " + r.requesterName); sendJson({ ok: true, status: "approved" }); }
            catch (e) { sendJson({ ok: false, error: "seal failed: " + String((e && e.message) || e) }, 500); }
        });
        return;
    }
    if (req.method === "GET" && req.url.split("?")[0] === "/key/result") {   // requester polls; envelope is sealed to them
        const id = new URLSearchParams(req.url.split("?")[1] || "").get("id") || "";
        const r = _keyRequests.get(id);
        if (!r) { sendJson({ ok: false, error: "no such request" }); return; }
        if (r.status === "approved") { sendJson({ ok: true, status: "approved", keyName: r.keyName, envelope: r.envelope }); return; }
        sendJson({ ok: true, status: r.status });
        return;
    }
    if (req.method === "POST" && req.url.split("?")[0] === "/key/ack") {   // requester confirms receipt -> holder drops it
        readJson((d) => { const id = String((d && d.id) || ""); if (_keyRequests.has(id)) { _keyRequests.delete(id); console.log("[keymove] delivered + acked " + id); } sendJson({ ok: true }); });
        return;
    }
    if (req.method === "POST" && req.url.split("?")[0] === "/key/store") {   // requester (local) persists a RECEIVED key
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson((d) => {
            const keyName = String((d && d.keyName) || ""), value = String((d && d.value) || "");
            if (!keyTransfer.keyEligible(keyName)) { sendJson({ ok: false, error: "not a storable key" }); return; }
            if (!value) { sendJson({ ok: false, error: "empty value" }); return; }
            try {
                if (keyName === "ha") { haBridge.setConfig({ token: value }); }
                else { aiCreds.saveApiKey(keyName, value); if (keyName === "gemini") { try { geminiCommentator.setKey(value); } catch {} } }
                console.log("[keymove] stored received '" + keyName + "'");
                sendJson({ ok: true, stored: keyName });
            } catch (e) { sendJson({ ok: false, error: String((e && e.message) || e) }, 500); }
        });
        return;
    }
    // v1749 - incremental self-update. Body is the package JSON (or { file:"<path>" } / { package:{...} }), optional restart.
    if (req.method === "POST" && req.url.split("?")[0] === "/update/apply") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson(async (d) => {
            let pkg = d, restart = !(d && d.restart === false);
            try { if (d && d.file) pkg = JSON.parse(require("fs").readFileSync(String(d.file), "utf8")); else if (d && d.package) pkg = d.package; }
            catch (e) { sendJson({ ok: false, error: "could not read package: " + (e && e.message) }); return; }
            const r = await _applyIncremental(pkg, { restart });
            sendJson(r);
        });
        return;
    }
    if (req.method === "GET" && req.url.split("?")[0] === "/update/status") { sendJson({ ok: true, current: _currentVersion(), last: _lastUpdate }); return; }
    // v1750 - Drive auto-pull: manual check + status (status never returns the service-account key)
    if (req.method === "POST" && req.url.split("?")[0] === "/update/drive/check") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        _driveCheck().then((r) => sendJson(r)).catch((e) => sendJson({ ok: false, error: String(e && e.message) }, 500));
        return;
    }
    // v1860 — RECEIVE a pushed update package from a credentialed peer (Galaxina detects a new Drive
    // update and fans it out). Dedup by fileId so a re-push doesn't re-apply / restart-loop. The receiver
    // does NOT re-push (no fan-out here) — only the credentialed poller fans out, so pushes never cascade.
    if (req.method === "POST" && req.url.split("?")[0] === "/update/drive/receive-push") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        readJson(async (d) => {
            try {
                const pkg = d && d.package, fileId = String((d && d.fileId) || "");
                const fromName = String((d && d.fromName) || "a peer");
                if (!pkg) { sendJson({ ok: false, error: "no package" }); return; }
                // dedup: if we already applied this exact Drive fileId, skip (prevents restart loops).
                if (fileId && fileId === _driveLastFileId && _driveLastApplied) { sendJson({ ok: true, skipped: "already applied", fileId }); return; }
                const result = await _applyIncremental(pkg, { restart: true });
                if (result && result.ok && fileId) { _driveLastFileId = fileId; _driveLastApplied = true; }
                console.log("[drive] applied pushed update from " + fromName + (result && result.toVersion ? (" (" + result.toVersion + ")") : ""));
                sendJson({ ok: !!(result && result.ok), applied: !!(result && result.ok), fileId, result });
            } catch (e) { sendJson({ ok: false, error: String(e && e.message || e) }); }
        });
        return;
    }
    // v1859 — SERVE the newest Drive update package to a peer that lacks Drive credentials. This peer
    // pulls from Drive with ITS OWN token (which never leaves this box) and returns just the package
    // JSON; the requesting peer applies it locally. Only serves if this box actually has creds. LAN-only
    // (trusted) so a random remote can't harvest your update stream.
    if (req.method === "GET" && req.url.split("?")[0] === "/update/drive/serve") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        (async () => {
            const c = _driveConfig();
            if (!c.folderId || (!c.saKey && !c.oauth)) { sendJson({ ok: false, reason: "no drive creds on this peer" }); return; }
            const deps = { folderId: c.folderId };
            if (c.oauth) deps.getToken = () => driveOauth.refreshAccessToken(c.oauth); else deps.saKey = c.saKey;
            // capture the package instead of applying it locally.
            let captured = null;
            deps.applyPackage = (pkg) => { captured = pkg; return { ok: true, served: true }; };
            try {
                const r = await driveSync.checkOnce(deps);
                if (!r || !r.found) { sendJson({ ok: true, found: false, servedBy: _selfId() }); return; }
                if (!captured) { sendJson({ ok: true, found: true, fileId: r.fileId, name: r.name, package: null, note: "already-current on server side", servedBy: _selfId() }); return; }
                sendJson({ ok: true, found: true, fileId: r.fileId, name: r.name, package: captured, servedBy: _selfId(), servedName: (function(){try{return peerIdentity.self().name}catch{return ""}})() });
            } catch (e) { sendJson({ ok: false, error: String(e && e.message || e) }); }
        })();
        return;
    }
    // v1859 — pull the update THROUGH a peer that holds Drive creds (when this box has none). Asks known LAN
    // peers who advertise driveCreds (via /self/whoami), then hits credentialed peers' /update/drive/serve and
    // takes the FIRST that returns a package ("most idle answers first"), applying it locally. The credential
    // never crosses the wire — the credentialed peer does the Drive pull and hands back only the update JSON.
    if (req.method === "POST" && req.url.split("?")[0] === "/update/drive/via-peer") {
        if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; }
        (async () => {
            // if THIS box has creds, just use them directly.
            try { const c = _driveConfig(); if (c.folderId && (c.oauth || c.saKey)) { const r = await _driveCheck(); sendJson(Object.assign({ ok: true, via: "self" }, r)); return; } } catch {}
            let peers = []; try { peers = assetSync.loadPeers(); } catch {}
            if (!peers.length) { sendJson({ ok: false, error: "no peers to ask (and this box has no Drive creds)" }); return; }
            // find credentialed peers by asking whoami in parallel; keep the ones that report driveCreds.
            const cred = (await Promise.all(peers.map(async (u) => {
                const base = String(u || "").replace(/\/+$/, ""); const url = /^https?:/.test(base) ? base : ("http://" + base);
                try { const w = await fetch(url + "/self/whoami", { signal: AbortSignal.timeout(2500) }).then(r => r.json()); return (w && w.driveCreds) ? { url, name: w.name || base } : null; } catch { return null; }
            }))).filter(Boolean);
            if (!cred.length) { sendJson({ ok: false, error: "no peer has Drive credentials — connect Drive on one box (e.g. Galaxina) first" }); return; }
            // ask them all at once; take the FIRST that returns a package (idle boxes answer first).
            let served = null, lastErr = "";
            await new Promise((resolve) => {
                let pending = cred.length, settled = false;
                for (const p of cred) {
                    const url = /^https?:/.test(p.url) ? p.url : ("http://" + p.url);
                    fetch(url + "/update/drive/serve", { signal: AbortSignal.timeout(20000) }).then(r => r.json()).then((j) => {
                        if (!settled && j && j.ok && j.found && j.package) { settled = true; served = { from: p, j }; resolve(); }
                        else { if (j && j.error) lastErr = j.error; else if (j && !j.found) lastErr = "peer reports no newer update"; if (--pending === 0 && !settled) { settled = true; resolve(); } }
                    }).catch((e) => { lastErr = String(e && e.message || e); if (--pending === 0 && !settled) { settled = true; resolve(); } });
                }
                if (pending === 0 && !settled) resolve();
            });
            if (!served) { sendJson({ ok: true, found: false, note: "asked " + cred.length + " credentialed peer(s); none had a newer update" + (lastErr ? (" (" + lastErr + ")") : ""), askedPeers: cred.map(c => c.name) }); return; }
            // apply the package this peer fetched from Drive on our behalf.
            try {
                const result = await _applyIncremental(served.j.package, { restart: true });
                sendJson({ ok: !!(result && result.ok), via: "peer", servedBy: served.from.name, fileName: served.j.name, result });
            } catch (e) { sendJson({ ok: false, via: "peer", servedBy: served.from.name, error: "apply failed: " + String(e && e.message || e) }); }
        })();
        return;
    }
    // v1818 — generate a Homebrew formula for `brew install swek-engine`. Computes the
    // real sha256 of the latest engine zip in the Downloads folder and emits the Ruby
    // formula + the tap/install commands + the one-time publishing steps.
    // v1819 — one-button steps 1-3: publish a GitHub release with the engine zip,
    // create the public homebrew-swek tap repo (if absent), and commit the formula.
