            if (!name) { try { name = remoteVisitors.nameFor(ip); } catch {} }
            if (!text) { sendJson({ ok: false, error: "empty" }); return; }
            const t = _visitorThread(ip);
            if (!_visitorRateOk(t)) { sendJson({ ok: false, error: "slow down a moment" }, 429); return; }
            if (name) { try { if (!remoteVisitors.nameFor(ip)) remoteVisitors.setName(ip, name); } catch {} }
