        const ctrl = (cmd, args) => { try { broadcast({ type: "control", cmd, args: args || {}, role: "commander", id: "push2run", name: "Push2Run" }); } catch (e) {} return cmd; };
        // v1989 — Push2Run can now drive INSTALL/SERVICE actions, not just the running
