        const _skGuessArch = (n) => { n = (n || "").toLowerCase(); if (/scout|light|recon/.test(n)) return "scout"; if (/heavy|assault|tank|brute/.test(n)) return "heavy"; if (/art|missile|mortar|siege/.test(n)) return "arty"; return "trooper"; };
        const _skWalk = (dir, base, out, imgs) => { let ents = []; try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; } for (const e of ents) { const rel = base ? base + "/" + e.name : e.name; if (e.isDirectory()) _skWalk(path.join(dir, e.name), rel, out, imgs); else if (/\.stl$/i.test(e.name)) out.push(rel); else if (imgs && /\.(jpg|jpeg|png)$/i.test(e.name)) imgs.push(rel); } };
        const _skScanMods = (modsDir) => { let dirs = []; try { dirs = fs.readdirSync(modsDir, { withFileTypes: true }).filter(e => e.isDirectory()); } catch { return []; } return dirs.map(d => { const rels = [], imgs = []; _skWalk(path.join(modsDir, d.name), "", rels, imgs); const url = (rel) => "/GPU_Assets/mods/" + d.name + "/" + rel.split("/").map(encodeURIComponent).join("/"); const tops = [...new Set(rels.map(r => r.split("/")[0]))].sort(); const files = rels.map((rel, i) => { const top = rel.split("/")[0]; const faction = tops.length >= 2 ? (top === tops[0] ? "A" : top === tops[1] ? "B" : (i % 2 ? "B" : "A")) : (i % 2 ? "B" : "A"); return { name: path.basename(rel), rel, url: url(rel), archetype: _skGuessArch(rel), faction }; }); const cards = imgs.filter(r => /card/i.test(r)).map(rel => ({ name: path.basename(rel), rel, url: url(rel) })); return { name: d.name, files, cards }; }); };
