        sendJson({ ok: true, mood: avatarMood.mood, score: avatarMood.score, reason: avatarMood.reason, style: avatarMood.style, cheer: avatarMood.cheer, talking: avatarMood.talking, ts: avatarMood.ts, quips, tama: nudge });
        return;
