    if (req.method === "POST" && req.url === "/ball/config") { readJson(d => sendJson({ ok: true, config: ballAlerts.setConfig((d && d.config) || d || {}) })); return; }
    if (req.method === "POST" && req.url === "/ball/event")  { readJson(d => { Promise.resolve(ballAlerts.fire(String((d && d.event) || ""))).then(r => sendJson(r || { ok: true })).catch(e => sendJson({ ok: false, error: String((e && e.message) || e) })); }); return; }
