    if (req.method === "POST" && req.url === "/tvnotify/test") { if (!_isTrustedReq(req)) { sendJson({ ok: false, error: "trusted only" }, 403); return; } readJson(d => { tvNotify.onEvent(String((d && d.event) || "genDone"), (d && d.detail) || {}).then(r => sendJson(r || { ok: true })).catch(e => sendJson({ ok: false, error: String(e && e.message || e) })); }); return; }
    if (req.method === "POST" && req.url === "/ball/test")   { readJson(d => { Promise.resolve(ballAlerts.pulse(String((d && d.style) || "blip"), (d && d.color) || null)).then(r => sendJson(r || { ok: true })).catch(e => sendJson({ ok: false, error: String((e && e.message) || e) })); }); return; }
