    // v1342 — multi-runtime link view: which runtimes are connected to the bridge,
    // last-seen freshness, and what state/intents flow over each link. Read-only,
    // derived from existing trackers (bridgeState ticks, KPop sentinel, WS clients).
    if (req.method === "GET" && req.url === "/bridge/runtimes") {
        const now = Date.now();
        const isBun = typeof Bun !== "undefined" || !!(process.versions && process.versions.bun);
        const band = (age) => age == null ? "never" : (age < 10000 ? "online" : (age < 5 * 60 * 1000 ? "stale" : "offline"));
        const runtimes = [];

        // hub — this bridge process
        runtimes.push({
            id: "bridge", label: isBun ? "Bun bridge" : "Node bridge", kind: "hub",
            role: "router · owns the intents / directives queue", state: "online", ageMs: 0,
            detail: { runtime: isBun ? "bun" : "node", version: isBun ? (process.versions.bun || "?") : (process.versions.node || "?"), pid: process.pid, uptimeSec: Math.round((process.uptime && process.uptime()) || 0), port: PORT }
        });

        // VBA / Excel — authoritative game state, posts /bridge/game_tick
        const vbaAge = bridgeState.lastTickMs > 0 ? now - bridgeState.lastTickMs : null;
        runtimes.push({
            id: "vba", label: "VBA / Excel engine", kind: "runtime",
            role: "owns authoritative game state — positions · physics · collision", state: band(vbaAge), ageMs: vbaAge,
            detail: { totalTicks: bridgeState.totalTicks || 0, queuedDirectives: (bridgeState.directives || []).length, link: "POST /bridge/game_tick ⇄ directives drained back" }
        });

        // PowerShell · KPop Listener — sentinel freshness
        let kAge = null;
        try { const st = fs.statSync(KPOP_SENTINEL); kAge = now - st.mtimeMs; } catch {}
        runtimes.push({
            id: "kpop", label: "PowerShell · KPop Listener", kind: "runtime",
            role: "audio / voice listener (Python + PS) — pushes clips & gauges", state: band(kAge), ageMs: kAge,
            detail: { link: "sentinel %TEMP%/KPopListener/Listener_Alive.txt" }
        });

        // WebGL clients — browsers / Shield over WebSocket
        let cnt = 0, newest = null; const by = { pc: 0, phone: 0, shield: 0 };
        try { for (const c of wss.clients) { if (c.readyState !== 1) continue; cnt++; const dev = c._clientDevice || c._clientRole || "pc"; if (by[dev] != null) by[dev]++; const age = now - (c._connectedAt || now); if (newest == null || age < newest) newest = age; } } catch {}
        runtimes.push({
            id: "webgl", label: "WebGL clients", kind: "runtime",
            role: "browser / Shield renderers — own intents, receive state", state: cnt > 0 ? "online" : "offline", ageMs: newest,
            detail: { count: cnt, pc: by.pc, phone: by.phone, shield: by.shield, link: "WebSocket :" + PORT + " · bridge:state broadcast" }
        });

        sendJson({ ok: true, runtimes, ts: now });
        return;
    }
    if (req.method === "GET" && req.url === "/install/history") {
        // WHAT THE BROWSER CANNOT MEASURE, SERVED TO THE BROWSER. Newest first, with new-build and restart
        // averages KEPT APART -- one average over both would describe neither.
        try { return sendJson(_installHistory.report(ENGINE_ROOT)); }
        catch (e) { return sendJson({ ok: false, error: String((e && e.message) || e) }, 500); }
    }
    if (req.method === "GET" && req.url === "/runtime") {
        const isBun = typeof Bun !== "undefined" || !!(process.versions && process.versions.bun);
        let bunAvail = isBun;
        if (!bunAvail) { try { require("child_process").execSync(process.platform === "win32" ? "where bun" : "which bun", { stdio: "ignore", timeout: 3000, windowsHide: true }); bunAvail = true; } catch {} }
        // v1202 — probe optional deps ONCE and cache. These 11 sync require()s ran
        // on EVERY /runtime call, blocking the single-threaded event loop long
        // enough that the very next POST /runtime/prefer queued behind it — so the
        // settings card sat on "Bun: checking..." / "saving..." forever. Cached now.
        if (!_runtimeFeatureCache) {
            const probe = (name) => { try { require(name); return { ok: true }; } catch (e) { return { ok: false, error: String((e && e.message) || e).slice(0, 140) }; } };
            const features = {
                "discord.js":        probe("discord.js"),
                "@discordjs/voice":  probe("@discordjs/voice"),
                "ffmpeg-static":     probe("ffmpeg-static"),
                "libsodium-wrappers": probe("libsodium-wrappers"),
                "opusscript":        probe("opusscript"),
                "openrgb-sdk":       probe("openrgb-sdk"),
                "mqtt":              probe("mqtt"),
                "aedes":             probe("aedes"),
                "bonjour-service":   probe("bonjour-service"),
                "selfsigned":        probe("selfsigned"),
                "ws":                probe("ws"),
            };
            _runtimeFeatureCache = { features, degraded: Object.keys(features).filter(k => !features[k].ok) };
        }
        const features = _runtimeFeatureCache.features, degraded = _runtimeFeatureCache.degraded;
        res.writeHead(200, JSONH);
        res.end(JSON.stringify({
            runtime: isBun ? "bun" : "node",
            version: isBun ? (process.versions.bun || "?") : process.versions.node,
            node: process.versions.node || null,
            bun: (process.versions && process.versions.bun) || null,
            useBun: (fs.existsSync(path.join(os.homedir(), ".voxelbridge", "use_bun.flag")) || fs.existsSync(path.join(__dirname, "use_bun.flag"))),
            bunAvailable: bunAvail,
            features,
            degraded,
            voiceReady: features["@discordjs/voice"].ok && features["discord.js"].ok,
        }));
        return;
    }
    // v3968 -- THE BROWSER HALF OF THE BRAIN LESSON CORPUS.
    //
    // brain/rl/lessons.mjs writes straight to disk under Node, and a browser cannot. brain-lab.html is the ONE
    // place in this tree that runs createWatchdog today, so without this route the only surface that currently
    // produces stall/revert verdicts could not contribute a single record -- the corpus would accumulate only
    // from Node drivers, and the page that actually trains policies in front of a person would be silent.
    //
    // ONE FILE, ONE OWNER. The path comes from lessons.mjs rather than being re-spelled here, so the browser
    // and Node halves cannot drift into writing two corpora that each look complete.
    if (req.url.split("?")[0] === "/brain/lessons") {
        const lessons = () => import(require("url").pathToFileURL(path.join(ENGINE_ROOT, "brain", "rl", "lessons.mjs")).href);
        if (req.method === "GET") {
            lessons().then((L) => {
                const all = L.readLessons();
                const u = new URL(req.url, "http://x");
                const env = (u.searchParams.get("env") || "").trim().toLowerCase();
                const rows = env ? all.filter((r) => String(r.env || "").toLowerCase().includes(env)) : all;
                sendJson({ ok: true, path: L.lessonsPath(), total: all.length, count: rows.length,
                           lessons: rows.slice(-500) });
            }).catch((e) => sendJson({ ok: false, error: String((e && e.message) || e) }));
            return;
        }
        if (req.method === "POST") {
            // The body is ONE JSON record, exactly what recordLesson() built browser-side. It is re-validated
            // through makeRecord rather than appended raw: a route that appends whatever arrives is a way to
            // write arbitrary lines into a file the engine later reads back and trusts.
            let body = ""; req.on("data", (c) => { body += c; if (body.length > 8192) req.destroy(); });
            req.on("end", () => {
                lessons().then((L) => {
                    let d = null; try { d = JSON.parse(body || "{}"); } catch { }
                    if (!d || typeof d !== "object") { sendJson({ ok: false, error: "not a JSON record" }); return; }
                    const wrote = L.recordLesson(d);
                    sendJson({ ok: !!wrote, written: !!wrote, health: L.health() });
                }).catch((e) => sendJson({ ok: false, error: String((e && e.message) || e) }));
            });
            return;
        }
    }
    // v3967 -- RUN tools/ship/bunSurface.mjs UNDER A NAMED RUNTIME AND HAND BACK ITS JSON.
    //
    // The point of that tool is COMPARISON: the same probes under Node and under Bun, where a difference is the
    // answer and a shared failure is the box. Doing that by hand means two terminals and a diff, on a rig that
    // is usually being driven from a browser -- so the page gets a button and this is what it calls.
    //
    // *** THE RUNTIME IS AN ALLOWLIST, NOT A PARAMETER. *** It picks between two fixed spellings and spawns one
    // fixed script. A route that took a command, or an interpreter path, from the query string would be a
    // remote shell wearing a diagnostic's clothes -- and this box exposes a tunnel.
    if (req.method === "GET" && req.url.split("?")[0] === "/runtime/surface") {
        const want = new URL(req.url, "http://x").searchParams.get("rt") === "bun" ? "bun" : "node";
        const script = path.join(ENGINE_ROOT, "tools", "ship", "bunSurface.mjs");
        if (!fs.existsSync(script)) { sendJson({ ok: false, error: "tools/ship/bunSurface.mjs is not in this tree" }); return; }
        // `node` is THIS process's own executable rather than the name "node": a box can be running the bridge
        // under a Node that is not the one on PATH, and the surface of the runtime serving this page is the one
        // the page is asking about. For bun there is no such handle, so the PATH name is all there is -- and a
        // box without bun gets a clean "not installed" instead of a spawn error nobody can read.
        const cmd = want === "bun" ? "bun" : process.execPath;
        require("child_process").execFile(cmd, [script, "--json"], { timeout: 120000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
            (err, stdout, stderr) => {
                if (err && !stdout) {
                    sendJson({ ok: false, runtime: want,
                               error: want === "bun" && /ENOENT|not found/i.test(String(err.message || ""))
                                   ? "bun is not on PATH on this box -- install it, or run the Node column only"
                                   : String((err && err.message) || err).slice(0, 300) });
                    return;
                }
                try { sendJson(Object.assign({ ok: true }, JSON.parse(stdout))); }
                catch (e) { sendJson({ ok: false, runtime: want, error: "bunSurface did not return JSON", out: String(stdout).slice(0, 400), err: String(stderr).slice(0, 200) }); }
            });
        return;
    }
    // v3997 -- RUN tools/roundhouse/runtimeBench.mjs UNDER A NAMED RUNTIME AND HAND BACK ITS JSON.
    //
    // A SECOND FIXED ROUTE RATHER THAN A SCRIPT PARAMETER ON THE FIRST ONE, and that is the whole design note.
    // /runtime/surface's own header says "THE RUNTIME IS AN ALLOWLIST, NOT A PARAMETER... a route that took a
    // command, or an interpreter path, from the query string would be a remote shell wearing a diagnostic's
    // clothes". Adding `&script=` to it would have been exactly that, so the script stays hardcoded here too and
    // the only thing the caller chooses is which of two spellings to spawn.
